window.NIGHTS.cases[2]={"nr":2,"id":"case02","title":"Kirmes der Maschinen","subtitle":"","level":"Persönliche Ebene","from":41,"to":60,"mythen":[],"sections":[{"id":"titel-und-pitch","kind":"intro","title":"Titel und Pitch","page":41,"layer":null,"blocks":4},{"id":"der-mechanist","kind":"place","title":"DER MECHANIST","page":42,"layer":null,"blocks":4},{"id":"der-kirmes","kind":"place","title":"DER KIRMES","page":42,"layer":null,"blocks":5},{"id":"dreiecksbeziehung-in-der-innenstadt","kind":"place","title":"DREIECKSBEZIEHUNG IN DER INNENSTADT","page":43,"layer":null,"blocks":9},{"id":"jene-schicksalhafte-nacht","kind":"place","title":"JENE SCHICKSALHAFTE NACHT","page":43,"layer":null,"blocks":7},{"id":"schicht-0-aufhaenger","kind":"layer","title":"SCHICHT 0: AUFHÄNGER","page":44,"layer":null,"blocks":15},{"id":"goldie","kind":"place","title":"GOLDIE","page":45,"layer":"schicht-0-aufhaenger","blocks":8},{"id":"detektiv-holliday","kind":"place","title":"DETEKTIV HOLLIDAY","page":46,"layer":"schicht-0-aufhaenger","blocks":23},{"id":"schicht-1-desaster-in-der-innenstadt","kind":"layer","title":"SCHICHT 1: DESASTER IN DER INNENSTADT","page":47,"layer":null,"blocks":1},{"id":"ecke-pine-und-5th","kind":"place","title":"ECKE PINE UND 5TH","page":47,"layer":"schicht-1-desaster-in-der-innenstadt","blocks":23},{"id":"rondo-s-diner-und-shinobi-sushi","kind":"place","title":"RONDO‘S DINER UND SHINOBI SUSHI","page":48,"layer":"schicht-1-desaster-in-der-innenstadt","blocks":8},{"id":"schicht-2-ein-gut-geoelter-mechanismus","kind":"layer","title":"SCHICHT 2: EIN GUT GEÖLTER MECHANISMUS","page":50,"layer":null,"blocks":1},{"id":"die-wohnung-der-woodworths","kind":"place","title":"DIE WOHNUNG DER WOODWORTHS","page":50,"layer":"schicht-2-ein-gut-geoelter-mechanismus","blocks":11},{"id":"detektei-holliday","kind":"place","title":"DETEKTEI HOLLIDAY","page":50,"layer":"schicht-2-ein-gut-geoelter-mechanismus","blocks":12},{"id":"david-nguyens-wohnung","kind":"place","title":"DAVID NGUYENS WOHNUNG","page":51,"layer":"schicht-2-ein-gut-geoelter-mechanismus","blocks":20},{"id":"der-spuk","kind":"place","title":"DER SPUK","page":52,"layer":"schicht-2-ein-gut-geoelter-mechanismus","blocks":7},{"id":"schicht-3-eine-lustige-art-zu-sterben","kind":"layer","title":"SCHICHT 3: EINE LUSTIGE ART ZU STERBEN","page":53,"layer":null,"blocks":1},{"id":"verlassener-rummelplatz","kind":"place","title":"VERLASSENER RUMMELPLATZ","page":53,"layer":"schicht-3-eine-lustige-art-zu-sterben","blocks":6},{"id":"auf-dem-rummelplatz","kind":"place","title":"AUF DEM RUMMELPLATZ","page":53,"layer":"schicht-3-eine-lustige-art-zu-sterben","blocks":35},{"id":"nachforschungen-auf-dem-verlassenen-rummelplatz","kind":"place","title":"NACHFORSCHUNGEN AUF DEM VERLASSENEN RUMMELPLATZ","page":56,"layer":"schicht-3-eine-lustige-art-zu-sterben","blocks":29},{"id":"schicht-4-wie-menschen-ticken","kind":"layer","title":"SCHICHT 4: WIE MENSCHEN TICKEN","page":59,"layer":null,"blocks":1},{"id":"der-kontrollraum","kind":"place","title":"DER KONTROLLRAUM","page":59,"layer":"schicht-4-wie-menschen-ticken","blocks":29}],"pages":{"41":{"tab":"","blocks":[{"t":"sh","x":"<b>EIN GRUSELIGER FALL UM MECHANISCHE WÜNSCHE</b>","sz":20.0,"box":[119.6,774.7,475.7,794.7],"p":41,"i":0,"sec":"titel-und-pitch"}],"size":[595.276,841.89]},"42":{"tab":"","blocks":[{"t":"p","x":"Als eine Dreiecksbeziehung zwischen Rissen in einem tragischen Autounfall endet, muss das Team die Kette der Ereignisse bis zu ihrem Ursprung zurückverfolgen. War es nur eine weitere traurige Geschichte, wie sie in dieser Stadt so häufig vorkommt, oder hatte jemand die Hand im Spiel? Bald sind die Mitglieder des Teams auf dem gleichen Weg ohne Wiederkehr, wie die Opfer des Verbrechens, das sie untersuchen.","sz":13.0,"box":[53.9,60.1,286.3,218.1],"p":42,"i":0,"sec":"titel-und-pitch"},{"t":"p","x":"<i>Kirmes der Maschinen</i> beginnt als Neon-Noir-Mordermittlung, schwenkt aber mitten im Fall in einen klassischen „Todesfalle„-Plot um, wie man ihn aus Comics kennt. In der stimmungsvollen ersten Hälfte deckt das Team in Ermittlungen das Unglück dreier Risse auf, die durch ihre Mythen miteinander verbunden sind. In der zweiten Hälfte des Falles legt das Team den Plan hinter den Tragödien offen und muss einen verlassenen und mit Sprengfallen versehenen Rummelplatz überleben, der nur dazu dient, sie und ihresgleichen zu töten. Es gibt mit Goldie einen NSC, dessen Schicksal von den Handlungen der SC direkt abhängt.","sz":9.5,"box":[53.9,237.1,285.0,384.1],"p":42,"i":1,"sec":"titel-und-pitch"},{"t":"p","x":"<i>MECHANISTIK: Die philosophische Lehre, dass alle Naturphänomene, einschließlich des Lebens und des Denkens, eine mechanische Erklärung durch Physik und Chemie erlauben.</i>","sz":9.5,"box":[53.9,432.0,277.2,479.0],"p":42,"i":2,"sec":"titel-und-pitch"},{"t":"h","x":"DER MECHANIST","sz":16.0,"box":[53.9,494.6,164.7,510.6],"p":42,"i":3,"skip":true,"sec":"der-mechanist"},{"t":"p","x":"<b>Maximilian Drake</b> glaubte einst, er könne alles verstehen. Für ihn waren das Universum, das Leben und die Menschen nichts weiter als komplizierte Maschinen, die man durch Analyse durchschauen konnte. Er war ein Genie der angewandten Wissenschaften und machte bahnbrechende Entdeckungen bei Helix Labs, ehe er als Riss des <b>Hephaistos</b>, des griechischen Gottes der Schmiede, Handwerker und Vulkane, erwachte. Nun sah er Dinge, die er nicht erklären konnte, und er wurde immer angsterfüllter. Erschwerend kam hinzu, dass er bei einem Laborunfall erwachte, und anschließend, an der Wirbelsäule verletzt, gehbehindert blieb. Geistig und körperlich gebrochen verließ er Helix Labs und seine geliebte Wissenschaft.","sz":9.5,"box":[53.9,514.6,283.5,686.6],"p":42,"i":4,"sec":"der-mechanist"},{"t":"p","x":"In seiner dunkelsten Stunde suchte Drake die Hilfe eines, wie er es nannte, „Hirnmechanikers„: des Psychiaters <b>Archibald Tennant</b>, Mitglied von <b>Heilung für</b>","sz":9.5,"box":[53.9,695.2,286.0,729.9],"p":42,"i":5,"sec":"der-mechanist"},{"t":"p","x":"<b>die Gebrochenen</b> (s. S. 63). Der ergriff die Gelegenheit und vergiftete Drakes Geist, indem er seine Logik- Besessenheit schürte und ihm einredete, die Kontrolle über sein Leben zurückzugewinnen, „indem er die Unbekannten in der Gleichung <i>eliminierte</i>„. Für Drake sind diese Unbekannten die Träger legendärer Kräfte: Risse, deren „Magie“ er sowohl verspottet als auch verabscheut. Drake verdrängt sein eigenes Riss-Sein und redet sich ein, seine Kräfte seien eine intellektuelle Evolution, die Ordnung in eine chaotische Welt bringt.","sz":9.5,"box":[309.0,62.5,540.0,184.5],"p":42,"i":6,"sec":"der-mechanist"},{"t":"h","x":"DER KIRMES","sz":16.0,"box":[309.0,200.2,391.6,216.2],"p":42,"i":7,"skip":true,"sec":"der-kirmes"},{"t":"p","x":"Als erfahrener Ingenieur nutzte Drake sein Genie, um Risse zu studieren und zu dekonstruieren. Durch die Analyse von Volksmärchen und Mythenkomparatistik gelang es ihm, die Muster zu entdecken, die Legenden bestimmen. Er erkannte die Logik der Kräfte der Risse und vor allem die treibende Kraft ihrer Legende. Daher vermutete er, dass die <b>Risse nicht anders können, als ihrem Mythos zu folgen</b>, und entwarf einen darauf basierenden Plan: Er beschloss einen Märchenpark zu bauen, der Risse in maßgeschneiderte Todesfallen lockt und tötet, wenn sie den mythischen Köder schlucken.","sz":9.5,"box":[309.0,220.1,541.1,367.1],"p":42,"i":8,"sec":"der-kirmes"},{"t":"p","x":"Dazu schloss er sich mit dem verarmten <b>Lemnos- Kirmes</b>, der vor den Toren der Stadt Station machte, und seinen Mitgliedern zusammen, die sich selbst als „<b>Schausteller</b>“ bezeichnen (die Sintoi, ein Volk von Plünderern, das nach Hephaistos‘ Sturz vom Olymp zu ihm hielt). Von Drakes Mythos berührt, akzeptierten die Lemnos-Schausteller:innen ihn als ihren Messias und verehrten ihn als Gott. Er schenkte ihnen die unheimliche Wissenschaft, die ihre Jahrmarktsattraktionen und Puppen zum Leben erweckt.","sz":9.5,"box":[309.0,375.7,538.1,497.7],"p":42,"i":9,"sec":"der-kirmes"},{"t":"p","x":"Um Informationen über potenzielle Ziele zu sammeln, heuerte Drake den <b>Privatdetektiv Tom Holliday</b> (Schläfer) an und stattete ihn mit einer Kamera aus, deren Linse durch den Nebel sehen kann. Er beauftragte den Privatdetektiv, Risse für ihn zu finden und ein Profil zu erstellen. Dann setzte er seine Schausteller:innen und ihre lebensechten Puppen ein, um die Zielpersonen in die Kirmes-Todesfalle zu locken.","sz":9.5,"box":[309.0,506.4,538.1,603.4],"p":42,"i":10,"sec":"der-kirmes"},{"t":"p","x":"Drakes Hypothese erwies sich als wahr. Fasziniert von dem fast mechanischen, vorhersehbaren Verhalten der Risse entwickelte Drake Fallen für jedes Opfer und schöpfte aus dem Sieg von Wissenschaft und Logik über seine legendäre Beute ein Gefühl von Kontrolle. Er tötete bis zu einem Dutzend Risse, ehe der Privatdetektiv Holliday ihm drei Profile von miteinander verbundenen Risse (und einer Schläferin) schickte, die für Drakes Intellekt ein interessantes Puzzle zum Lösen waren.","sz":9.5,"box":[309.0,612.1,537.5,734.1],"p":42,"i":11,"sec":"der-kirmes"}],"size":[595.276,841.89]},"43":{"tab":"","blocks":[{"t":"h","x":"DREIECKSBEZIEHUNG IN DER INNENSTADT","sz":16.0,"box":[53.9,62.2,214.4,95.2],"p":43,"i":0,"skip":true,"sec":"dreiecksbeziehung-in-der-innenstadt"},{"t":"p","x":"Drakes neue Ziele waren:","sz":9.5,"box":[53.9,99.2,160.4,108.7],"p":43,"i":1,"sec":"dreiecksbeziehung-in-der-innenstadt"},{"t":"p","x":"• <b>Pauline Woodworth</b> (Paul Bunyan, ein riesiger Holzfäller der amerikanischen Folklore), eine private Bauunternehmerin, die sowohl über immense Kraft als auch über die Fähigkeit verfügte, größer zu werden. Sie hatte ihr eigenes Unternehmen, <b>Woodworth-Bau</b>, und eine wunderschöne Frau, <b>Ellie Woodworth</b> (Schläferin). Ihr Mythos drängte sie, die Wildnis urbar zu machen, und so interessierte sie sich für Bauprojekte außerhalb der Stadt.","sz":9.5,"box":[53.9,120.2,284.6,229.7],"p":43,"i":2,"sec":"dreiecksbeziehung-in-der-innenstadt"},{"t":"p","x":"• <b>David Nguyen</b> (König David), ein hochrangiger Manager bei Orimaka Finance. Sein Mythos erlaubte es ihm, Riesen zu töten (David und Goliath), brachte ihn aber dazu, die Frau eines anderen zu begehren.","sz":9.5,"box":[53.9,238.3,282.7,285.3],"p":43,"i":3,"sec":"dreiecksbeziehung-in-der-innenstadt"},{"t":"p","x":"• Samantha Goldstein oder <b>Goldie</b> (Goldlöckchen) ist eine Meisterdiebin, die in jedes Haus eindringen, Schlösser, Alarmanlagen usw. umgehen kann und den Drang hat zu stehlen, was andere Leute besitzen.","sz":9.5,"box":[53.9,294.0,286.6,341.0],"p":43,"i":4,"sec":"dreiecksbeziehung-in-der-innenstadt"},{"t":"p","x":"Drake setzte die Intrigen in Gang, die sie in den Tod führen sollten:","sz":9.5,"box":[53.9,346.8,271.9,368.8],"p":43,"i":5,"sec":"dreiecksbeziehung-in-der-innenstadt"},{"t":"p","x":"• Er lockte Pauline mit dem Projekt, den verlassenen Rummelplatz am Rande der Stadt wieder aufzubauen (die Wildnis zu besiedeln).","sz":9.5,"box":[53.9,380.3,286.1,414.8],"p":43,"i":6,"sec":"dreiecksbeziehung-in-der-innenstadt"},{"t":"p","x":"• Er arrangierte für David ein schlechtes Date im selben Lokal, in dem Pauline und Ellie aßen, und sagte voraus, dass er sein Herz an Ellie verlieren würde.","sz":9.5,"box":[53.9,423.5,280.3,458.0],"p":43,"i":7,"sec":"dreiecksbeziehung-in-der-innenstadt"},{"t":"p","x":"• Während dieser Verabredung gab Holliday Goldie einen Tipp über einen reichen Mann im Downtown Diner, der ein gutes Ziel sein könnte. Sie tauchte auf und folgte David, um sein Geld zu stehlen.","sz":9.5,"box":[309.0,59.9,537.7,106.9],"p":43,"i":8,"sec":"dreiecksbeziehung-in-der-innenstadt"},{"t":"h","x":"JENE SCHICKSALHAFTE NACHT","sz":16.0,"box":[309.0,119.8,516.0,135.8],"p":43,"i":9,"skip":true,"sec":"jene-schicksalhafte-nacht"},{"t":"p","x":"Es vergingen Wochen, in denen David die Woodworths belästigte und Goldie herauszufinden versuchte, wo David sein Vermögen aufbewahrte. Eines Abends ging Drakes Plan in Erfüllung.","sz":9.5,"box":[309.0,139.7,538.2,186.7],"p":43,"i":10,"sec":"jene-schicksalhafte-nacht"},{"t":"p","x":"• David folgte Pauline auf den Rummelplatz, wo sie sich einen Kampf à la David und Goliath lieferten, bei dem er sie erschoss.","sz":9.5,"box":[309.0,198.2,527.9,232.7],"p":43,"i":11,"sec":"jene-schicksalhafte-nacht"},{"t":"p","x":"• Drake und seine Schausteller:innen hatten eine Todesfalle für David vorbereitet, eine lebensechte Puppe, die wie Ellie aussehen sollte. Als David sie küsste, brannten seine Lippen. Die Lippen der Puppe waren mit Gift präpariert.","sz":9.5,"box":[309.0,241.4,539.3,300.9],"p":43,"i":12,"sec":"jene-schicksalhafte-nacht"},{"t":"p","x":"• Als David merkte, dass man ihn getäuscht hatte, raste er zurück in die Stadt, um die echte Ellie zu finden und medizinische Hilfe zu bekommen, aber es war zu spät. Das Gift tötete ihn, und er verunglückte mit seinem Sportwagen in der Nähe des Diners, in dem sie sich kennengelernt hatten.","sz":9.5,"box":[309.0,309.5,539.7,381.5],"p":43,"i":13,"sec":"jene-schicksalhafte-nacht"},{"t":"p","x":"• Goldie sah den Unfall und ihr wurde klar, dass David in etwas Größeres verwickelt war und sie, um mehr zu erfahren, herausfinden musste, woher er gekommen war. Auf dem Rummelplatz wartet bereits eine maßgeschneiderte Todesfalle auf sie.","sz":9.5,"box":[309.0,390.2,537.2,449.7],"p":43,"i":14,"sec":"jene-schicksalhafte-nacht"},{"t":"p","x":"Der Fall beginnt mit dem Autounfall.","sz":9.5,"box":[309.0,455.5,465.0,465.0],"p":43,"i":15,"sec":"jene-schicksalhafte-nacht"}],"size":[595.276,841.89]},"44":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 0:","sz":14.0,"box":[53.9,484.4,122.3,498.4],"p":44,"i":0,"skip":true,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"AUFHÄNGER","sz":23.0,"box":[53.9,506.7,170.2,529.7],"p":44,"i":1,"skip":true},{"t":"p","x":"Der cineastische Start in den Fall ist, das Team nachts an der <u>Ecke Pine und 5th</u> den Unfall David Nguyens <b>miterleben zu lassen</b>. Direkt an einer belebten Kreuzung in der Innenstadt gelegen, könnten einige Teammitglieder im Alltagstrott als zufällige Passanten vor Ort sein. Präkognitive Risse könnten eine Vision des bevorstehenden Unfalls haben und rechtzeitig dort eintreffen, um ihn zu verhindern. Vielleicht trifft sich das Team auch zu einem späten Abendessen und einem Gespräch in einem Diner in der Nähe der Kreuzung, etwas in <u>Rondo‘s Diner oder Shinobi Sushi.</u>","sz":9.5,"box":[53.9,541.0,283.7,675.5],"p":44,"i":2,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Wer am Unfallort ist, hört zunächst das Röhren eines Sportwagenmotors und sieht dann das außer Kontrolle geratene Fahrzeug die 5th Street entlang rasen. Der Fahrer scheint bewusstlos zu sein, sein Kopf liegt auf dem Lenkrad. <b>Selbst wenn das Team den Wagen sicher zum Stehen bringt, ist David Nguyen tot</b>, umgebracht durch den Giftkuss der falschen Ellie.","sz":9.5,"box":[53.9,684.1,284.7,768.6],"p":44,"i":3,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"AUSSER KONTROLLE GERATENES AUTO","sz":12.0,"box":[317.5,499.2,508.6,511.2],"p":44,"i":4,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"★ ★★","sz":12.0,"box":[317.5,510.1,359.6,522.1],"p":44,"i":5,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"(+ )","sz":12.0,"box":[327.7,514.2,364.8,526.2],"p":44,"i":6,"sec":"schicht-0-aufhaenger"},{"t":"sh","x":"<b>SICHER ZUM STILLSTAND BRINGEN 2 / UNFALL 2</b>","sz":12.0,"box":[317.5,534.8,514.6,546.8],"p":44,"i":7,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Sportwagen</b>: Wenn das außer Kontrolle geratene Auto auftaucht, gib ihm <t>rasen 4</t>. • <b>Kollisionskurs</b>: Wenn <i>Unfall</i> den Maximalwert 2 erreicht, prallt das außer Kontrolle geratene Auto gegen jede harte Barriere, die sich anbietet.","sz":9.0,"box":[317.5,551.2,523.6,608.2],"p":44,"i":8,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• Auf etwas zurasen (<t>drohender Unfall 1</t>) • +★★: Jemanden rammen, der nicht aufpasst oder nicht ausweichen kann (<t>krankenhausreif 5</t> oder <b>Etwas Schreckliches geschehen lassen</b>)","sz":9.0,"box":[317.5,617.2,523.2,662.4],"p":44,"i":9,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• Mir röhrendem Motor die Straße entlangrasen • An einem Unbeteiligten vorbei rasen und einen Dopplereffekt erzeugen","sz":9.0,"box":[317.5,671.2,515.1,704.2],"p":44,"i":10,"sec":"schicht-0-aufhaenger"}],"size":[595.276,841.89]},"45":{"tab":"","blocks":[{"t":"p","x":"Du könntest das Team anders in den Fall einbeziehen:","sz":9.5,"box":[53.9,59.9,281.9,69.4],"p":45,"i":0,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• Wenn das Team den Ruf hat, auch illegal zu arbeiten, kann Davids Großmutter, <b>Theresa Nguyen</b>, es eine Stunde nach dem Unfall kontaktieren. Die ältere, äußerst wohlhabende Dame bietet am Telefon viel Geld für denjenigen, der ihr den Kopf des Verantwortlichen für den Tod ihres Enkels auf einem Silbertablett serviert. Wenn das Team ablehnt, wird sie zu jemand anderen gehen, lässt sich aber überzeugen, für Informationen über den Mörder ihres Enkels zu zahlen.","sz":9.5,"box":[53.9,80.9,286.3,190.4],"p":45,"i":1,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• Die <b>Beamten Das und Quinn</b>, die in <i>Der sanfte Tod</i> (s. S. 30) auftauchen, werden zu dem verunglückten Auto und dem Aufruhr im Zusammenhang damit gerufen. Wenn das Team eine gute Beziehung zu ihnen aufgebaut hat, könnten sie die SC um Hilfe bei den Ermittlungen zum Tod David Nguyens bitten.","sz":9.5,"box":[53.9,199.1,285.0,271.1],"p":45,"i":2,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"GAFFER","sz":23.0,"box":[53.9,299.0,126.3,322.0],"p":45,"i":3,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Während das Team den Schauplatz untersucht, beobachten zwei Menschen, mit großem Interesse an dem Unfall, die SC aus der Ferne. Aufmerksame SC, die <b>Nachforschungen</b> anstellen, und schauen, ob jemand sie beobachtet, können eine oder beide Individuen bemerken. Du kannst das Team wissen lassen, dass jemand sie beobachtet, wenn du die Personen einführen willst. Goldie könnte sich dem Team nähern und vorstellen (s. u.)","sz":13.0,"box":[53.9,329.9,285.9,502.4],"p":45,"i":4,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"GOLDIE","sz":16.0,"box":[53.9,520.0,101.9,536.0],"p":45,"i":5,"skip":true,"sec":"goldie"},{"t":"p","x":"<b>Samantha Goldstein (Goldlöckchen), bekannt als Goldie, spielt die Rolle der erlösbaren Verbrecherin</b>, ein NSC auf Abwegen, dessen Schicksal die SC bestimmen. Sie ist eine Diebin, darauf spezialisiert, bei reichen Leuten einzubrechen und sie zu berauben. Goldie hat einen ausgeprägten 80er-Jahre-Streetwear- Stil: Sie hat platinblond auftoupiertes Haar, eine zerrissene Jeansjacke und große Plastikohrringe. Sie kann unbelebte Gegenstände formen, indem sie erklärt, sie seien „zu heiß“, „zu kalt“, „zu groß“, „zu klein“, „zu hart“ oder „zu weich“, was sich dann ändert.","sz":9.5,"box":[53.9,540.0,284.1,674.4],"p":45,"i":6,"sec":"goldie"},{"t":"p","x":"<b>Goldie, die sich mythisch zum Besitz anderer Leute hingezogen fühlt, giert nach dem Vermögen von David Nguyen und wird alles tun, um herauszufinden, wo er etwas Wertvolles versteckt hat</b>, sei es Bargeld, Gold, Diamanten, Anleihen oder was auch immer. Diese legendäre Kleptomanie hat sie bereits in Maximilian Drakes Falle gelockt, die sorgfältig all ihre","sz":9.5,"box":[53.9,683.2,285.7,767.5],"p":45,"i":7,"sec":"goldie"},{"t":"threat","stars":"★★★","name":"GOLDIE","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 2 / ER- LÖSEN 5 / FESTNEHMEN 5","items":["<b>Fremder Besitz</b>: Einmal in der Serie kann Goldie ihre Zurückhaltung ablegen und ein einzelnes Objekt oder eine Macht, die jemand anderes besitzt, erlangen, solange sie entweder Objekt oder Besitzer sehen kann. Dann verlässt Goldie die Stadt.","<b>Zu heiß, zu kalt</b>: Einmal pro Szene kann Goldie ihre Kräfte zur Verteidigung einsetzen und einen einzelnen körperlichen Schaden von 5 oder weniger aufheben, indem sie ihn für zu heiß, zu kalt, zu hart, zu weich, zu groß oder zu klein erklärt.","Die Kleidung der Verfolger „zu hart“, „zu groß“ oder „zu klein“ machen (<t>verstrickt 3</t> oder <t>kann nicht atmen 3</t>), sie verlangsamen, indem sie den Boden „zu weich“ macht (<t>verlangsamt 3</t>) oder entkommen, indem sie einen Durchgang „zu klein“ macht, um zu folgen (<b>Ihnen etwas verweigern, das sie wollen</b>)","Etwas stehlen oder jemanden dazu zwingen, einen Gegenstand fallen zu lassen, indem sie ihn „zu heiß“ macht (bis zu zwei Stärken verbrennen und sich selbst entsprechende Stärken geben)","Fesselung entfliehen, indem Sie ein Objekt „zu groß“ macht, um sie zu fesseln oder einzusperren (entferne bis zu 3 Stufen des Fesselungs-Zustands oder verbrenne bis zu 3 Fesselungs-Stärken)","Umgehung von Sicherheitsvorkehrungen, indem sie Schlösser „zu klein“ und die Schaltkreise von Sicherheitssystemen „zu heiß“ macht, um zu funktionieren (ein Sicherheitssystem mit <t>überbrückt 3</t> versehen oder 3 seiner Stärken verbrennen)","Sich blitzschnell umdrehen, sich vor der Verantwortung drücken und alle Fortschritte, die sie gemacht hat, aufgeben (3 Stufen von jedem Zustand auf ihrem <i>Erlösen</i>-Spektrum oder 3 Schuld- oder Verantwortungs-Zustände entfernen)","Breit lächeln und ihr Haar schütteln, während sie entkommt"],"box":[355.9,58.0,386.5,70.0],"p":45,"i":8,"sec":"goldie"},{"t":"p","x":"Mythos-Knöpfe drückt. Wenn sie Davids Spur folgt und den <u>verlassenen Rummelplatz</u> erreicht, wie Drake es plant, wartet dort eine Todesfalle auf sie.","sz":9.5,"box":[309.0,585.0,541.1,619.5],"p":45,"i":9,"sec":"goldie"},{"t":"p","x":"<b>Goldie wird versuchen, das Team zu benutzen.</b> Wenn sie sieht, wie die SC den Unfall untersuchen, ist es für sie naheliegend, sich mit ihnen zusammenzutun. Sie wird das Team belügen, bestehlen und schließlich wahrscheinlich verraten, aber nur, solange niemand schwere Verletzungen davonträgt, denn dann erwacht ihr Gewissen für einen Moment. So könnte sie vorgeben, Ellie Woodworth zu sein und versuchen, das Team in <u>David Nguyens Wohnung</u> einzubrechen zu lassen oder ihr verraten, was sie über seinen letzten Aufenthaltsort wissen. Spiel sie als glaubwürdige, freund-","sz":9.5,"box":[309.0,628.3,541.7,762.7],"p":45,"i":10,"sec":"goldie"}],"size":[595.276,841.89]},"46":{"tab":"","blocks":[{"t":"p","x":"liche Verbündete, die das Team später achselzuckend hintergeht, als könne sie nichts dafür. Versuch, ihren Verrat eher spöttisch und humorvoll als schwerwiegend zu gestalten, und spiel ihren Charme aus, um das Team für ihr Schicksal zu interessieren.","sz":9.5,"box":[53.9,59.9,283.2,119.4],"p":46,"i":0,"sec":"goldie"},{"t":"p","x":"Goldie hat David Nguyen beschattet und kennt die Hinweise unter <b>Nachforschungen über David Nguyen</b> an der <u>Ecke Pine und 5th.</u> Sie kennt auch die Einzelheiten seiner Beziehung zu Pauline und Ellie Woodworth, die unter <u>Rondo‘s Diner und Shinobi Sushi</u> aufgeführt sind, und kann die SC auf den neuesten Stand bringen.","sz":9.5,"box":[53.9,128.1,281.5,212.6],"p":46,"i":1,"sec":"goldie"},{"t":"h","x":"DETEKTIV HOLLIDAY","sz":16.0,"box":[53.9,228.3,187.7,244.3],"p":46,"i":2,"skip":true,"sec":"detektiv-holliday"},{"t":"p","x":"Die andere Person, die den Fall im Auge behält, ist <b>Privatdetektiv Tom Holliday</b> (Schläfer), der für Maximilian Drake arbeitet, aber den Namen seines Auftraggebers nicht kennt oder und ihn nie getroffen hat (s. S. Textkasten). Mit klassischen Mantel und Filzhut ist der Privatdetektiv für die verregneten Gassen der Stadt gut gerüstet. Als starker Raucher hinterlässt er viele Zigarettenstummel, wenn er ein Ziel ausspäht.","sz":9.5,"box":[53.9,248.2,285.8,345.2],"p":46,"i":3,"sec":"detektiv-holliday"},{"t":"p","x":"<b>Holliday ist es egal, für wen er arbeitet. Eigentlich will er es gar nicht wissen,</b> sondern nur am Ende des Tages bezahlt werden. Holliday hält sich für die Probleme anderer Menschen („niemand ist unschuldig“) nicht verantwortlich, und er hat genug Leichen von Leuten gesehen, deren Probleme sie eingeholt haben, um sich zu kümmern. Er ist ein schmieriger Typ aber nicht böse. Wenn man ihn mit Beweisen, dass seine Arbeit Menschen schadet, konfrontiert, würde er darüber nachdenken, ob er noch einmal einen Job von diesem Auftraggeber annimmt.","sz":9.5,"box":[53.9,354.0,284.7,488.4],"p":46,"i":4,"sec":"detektiv-holliday"},{"t":"h","x":"DETEKTIV HOLLIDAYS ARBEITSWEISE","sz":14.0,"box":[324.1,67.5,498.5,81.5],"p":46,"i":5,"sec":"detektiv-holliday"},{"t":"p","x":"Detektiv Holliday kommuniziert ausschließlich per Brief mit seinem Auftraggeber und hat das Doppelte seines normalen Honorars für die Erstellung von Riss-Profilen erhalten. Er hat eine Spezialkamera, deren Linse den Nebel durchdringt, so dass er die wahre Gestalt und Kräfte eines Risses sehen und fotografieren kann (die Fotos, die er macht, offenbaren nur ihrem Träger und einem Riss legendäre Phänomene). Seitdem beschattet er Risse und schickt die Berichte an eine obskure Mailbox.","sz":9.0,"box":[324.1,94.0,526.0,211.0],"p":46,"i":6,"sec":"detektiv-holliday"},{"t":"p","x":"Zweimal täglich kontrolliert eine Schausteller:in den Briefkasten. Geh davon aus, dass Privatdetektiv Holliday alle Funde sofort an seinen Arbeitgeber meldet, vielleicht über eine Notrufnummer, wenn er meint, dass etwas wertvoll oder nützlich ist (dieselbe Schausteller:in geht ans Telefon). Sobald Drake die ersten Berichte über eine neue Gruppe von Rissen – das Team – erhält, fängt er an, maßgeschneiderte Fallen für sie zu bauen.","sz":9.0,"box":[324.1,219.7,523.5,324.7],"p":46,"i":7,"sec":"detektiv-holliday"},{"t":"sh","x":"<b>PROFILE DES TEAMS</b>","sz":10.0,"box":[309.4,352.6,421.7,362.6],"p":46,"i":8,"sec":"detektiv-holliday"},{"t":"p","x":"Wenn die SC im Laufe des Falles die Punkte 7-9 bei <b>Nachforschungen</b> erzielen, stelle ihnen Gegenfragen über ihren Mythos und ihre Mythoskräfte.","sz":9.5,"box":[309.0,368.2,535.6,402.7],"p":46,"i":9,"sec":"detektiv-holliday"},{"t":"p","x":"Wenn ein SC vor Privatdetektiv Hollidays Augen seine Kräfte einsetzt, frag:","sz":9.5,"box":[309.0,411.3,536.7,433.3],"p":46,"i":10,"sec":"detektiv-holliday"},{"t":"p","x":"• Welcher Art sind deine Kräfte? • Was könnte deiner Meinung nach deine Kräfte blockieren oder negieren? • Könnte man deine Kräfte gegen dich verwenden?","sz":9.5,"box":[309.0,439.2,532.4,486.2],"p":46,"i":11,"sec":"detektiv-holliday"},{"t":"p","x":"Wenn ein SC ein Verhalten zeigt, das mit seinem Mythos zusammenhängt, frag:","sz":9.5,"box":[309.0,492.0,532.1,514.0],"p":46,"i":12,"sec":"detektiv-holliday"},{"t":"p","x":"• Was will dein Mythos wirklich von dir? • Was sollst du für ihn herausfinden? • Welche Figur in deinem Mythos ist dir wichtig?","sz":9.5,"box":[309.0,519.9,515.9,554.4],"p":46,"i":13,"sec":"detektiv-holliday"},{"t":"p","x":"<b>Notiere die Antworten und verwende sie, wenn du die Todesfallen beschreibst, die Drake auf dem <u>verlassenen Rummelplatz</u> vorbereitet hat.</b> Sowohl Holliday als auch Drake werden das Team ausspionieren und aus wenigen Schlüsseldetails eine Menge Informationen ableiten.","sz":9.5,"box":[309.0,560.3,534.7,632.2],"p":46,"i":14,"sec":"detektiv-holliday"},{"t":"sh","x":"<b>DIE VERFOLGUNG PRIVATDETEKTIV HOL- LIDAYS</b>","sz":10.0,"box":[309.4,645.8,538.0,667.8],"p":46,"i":15,"sec":"detektiv-holliday"},{"t":"p","x":"Dem Privatdetektiv zu entkommen und ihn zu verfolgen ist nicht leicht. Seine Spezialaktion <b>Gewieft</b> und seine Kenntnis der Gassen der Innenstadt, die sich in <b>Ihnen etwas verweigern, das sie wollen</b>, widerspiegeln, machen ihn schwer zu beschatten. Wenn es dem Team geling, folgen sie ihm zu seinem Büro <u>(Detektei Holliday),</u> bei der Beschattung, in Begleitung Goldies oder sehen, wie er ein Paket in einen Briefkasten wirft.","sz":9.5,"box":[309.0,673.4,539.0,770.4],"p":46,"i":16,"sec":"detektiv-holliday"}],"size":[595.276,841.89]},"47":{"tab":"","blocks":[{"t":"sh","x":"<b>SCHIFFE IN DER NACHT</b>","sz":10.0,"box":[54.3,62.8,183.1,72.8],"p":47,"i":0,"sec":"detektiv-holliday"},{"t":"p","x":"Um die Dinge komplizierter zu machen, hat sich Holliday in Goldie verliebt, als er in den letzten Wochen ihr Profil erstellte. Er ist ihr näher gekommen, oder, besser gesagt, er hat sich von ihr sehen lassen, und die beiden haben nun eine unverbindliche Affäre. David Nguyens Autounfall lässt den Privatdetektiv darüber nachdenken, was sein Arbeitgeber mit Goldie vorhat, die Sorge um sie könnte ihn dazu bringen, seine Grenzen zu überschreiten und sich auf sie einzulassen.","sz":9.5,"box":[53.9,78.3,285.3,187.8],"p":47,"i":1,"sec":"detektiv-holliday"},{"t":"p","x":"Goldie kann dem Team helfen, Holliday zu erreichen, aber es funktioniert beidseitig: Informationen über das Team, ihre Kräfte und Pläne können durch Goldie zu Holliday und von dort zu Drake durchsickern.","sz":9.5,"box":[53.9,196.5,285.7,243.5],"p":47,"i":2,"sec":"detektiv-holliday"},{"t":"h","x":"PRIVATDETEKTIV HOLLIDAY ★★","sz":12.0,"box":[62.4,289.4,221.1,305.6],"p":47,"i":3,"sec":"detektiv-holliday"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 3 / BE- STECHEN 4 / BEDROHEN 4</b>","sz":12.0,"box":[62.4,314.1,264.6,338.1],"p":47,"i":4,"sec":"detektiv-holliday"},{"t":"p","x":"• <b>Fähigkeit der Deduktion</b>: Wenn Holliday einen Tatort zum ersten Mal untersucht oder als harte Aktion stellt die SL eine Frage. Die befragte Spieler:in muss mit einer direkten Antwort oder soliden Hinweis antworten. Holliday kennt die Antwort, auch wenn der SC sie nicht ausgesprochen hat. • <b>Gewieft</b>: Wann immer jemand versucht, Holliday zu folgen oder zu täuschen, gib ihm <t>aufmerksam 2</t>. Dieser Zustand darf Stufe 3 nicht überschreiten. • <b>Schnelles Denken</b>: Wenn Holliday einen Zustand erleidet, den er mit gesundem Menschenverstand oder Einfallsreichtum schwächen kann, verringert sich dessen Stufe um 1. • <b>Professionalität</b>: Wenn die SC das erste Mal in einer Szene versuchen, von Holliday Informationen über seinen Arbeitgeber zu erhalten, gib ihm <t>meine Lippen sind versiegelt 3</t>, wenn <i>Bestechen</i> oder <i>Bedrohen</i> noch nicht ihren Maximalwert erreicht haben.","sz":9.0,"box":[62.4,342.6,276.8,567.6],"p":47,"i":5,"sec":"detektiv-holliday"},{"t":"p","x":"• Revolver ziehen und jemanden auffordern, sich zurückzuziehen, weil er sonst schießt (<t>vorsichtig 2</t> oder <t>Schusswunde 3</t>) • In einer nebligen Gasse verschwinden oder jemanden abhängen, der ihn beschatten will (<b>Ihnen etwas verweigern, das sie wollen</b>) • Jemanden schmieren, wenn die Person Probleme macht (<i>Bündel Geld</i> geben, wenn sie verschwindet)","sz":9.0,"box":[62.4,576.6,272.0,669.6],"p":47,"i":6,"sec":"detektiv-holliday"},{"t":"p","x":"• Von einer Straßenecke aus schweigend und rauchend beobachten","sz":9.0,"box":[62.4,678.6,262.8,699.6],"p":47,"i":7,"sec":"detektiv-holliday"},{"t":"h","x":"SCHICHT 1:","sz":14.0,"box":[309.0,69.1,376.0,83.1],"p":47,"i":8,"skip":true,"sec":"schicht-1-desaster-in-der-innenstadt"},{"t":"h","x":"DESASTER IN DER INNENSTADT","sz":23.0,"box":[309.0,91.4,473.5,142.4],"p":47,"i":9,"skip":true},{"t":"h","x":"ECKE PINE UND 5TH","sz":16.0,"box":[334.8,156.0,466.3,172.0],"p":47,"i":10,"skip":true,"sec":"ecke-pine-und-5th"},{"t":"ro","x":"Aus dem Motor des verunglückten Sportwagens steigt Qualm auf, und der beißende Geruch von verbrannten Gummis erfüllt die Luft. Die Lichter des Wagens blinken im Takt mit der Leuchtreklame eines Restaurants, was in der Kakophonie der Alarmanlagen der ringsum parkenden Autos untergeht. Die Straßenlaterne über der Kreuzung Pine und 5th Street flackert und erlischt. Die Windschutzscheibe, die in Millionen von Glassplittern zerborsten ist, hängt noch tapfer in ihrem Rahmen und verbirgt bis auf einen großen Blutfleck alles, was dahinter liegt.","sz":9.0,"box":[317.5,174.4,538.9,323.8],"p":47,"i":11,"sec":"ecke-pine-und-5th"},{"t":"p","x":"Die Ecke Pine und 5th Street ist eine belebte Kreuzung in der Innenstadt, nahe einiger Geschäfte und beliebten Schnellrestaurants. Hier hat David Nguyens seinen Unfall, und hier, in <u>Rondo‘s Diner,</u> begann die einseitige Dreiecksbeziehung zu Pauline und Ellie Woodworth. Die <u>Wohnung der Woodworths</u> ist nur einen Block entfernt. Die Leute hier kennen sie von früheren Besuchen, zumindest vom Sehen.","sz":9.5,"box":[309.0,332.8,541.7,429.8],"p":47,"i":12,"sec":"ecke-pine-und-5th"},{"t":"p","x":"Nach dem Unfall strömen Schaulustige heran, bald gefolgt von einem Krankenwagen und der Polizei (möglicherweise die Beamten Das und Quinn), die den Tatort absperren und die Menschen zurückdrängen. Wenn das Team zuerst da ist, können die SC das Auto und den Fahrer untersuchen (<b>Nachforschungen</b>), bevor die Polizei eintrifft, aber sie werden dabei gesehen (es sei denn, sie nutzen <b>Heimlichkeit</b> oder sorgen für eine dramatische Ablenkung).","sz":9.5,"box":[309.0,438.5,537.7,548.0],"p":47,"i":13,"sec":"ecke-pine-und-5th"},{"t":"h","x":"TOD DURCH GLAS","sz":14.0,"box":[320.3,572.5,400.8,586.5],"p":47,"i":14,"sec":"ecke-pine-und-5th"},{"t":"p","x":"Der Leichnam des Fahrers ist durch den Unfall in einem grausigen Zustand, er hat eine große Glasscherbe im Schädel. Moderne Windschutzscheiben gehen so nicht zu Bruch, eine Tatsache, die du erwähnen kannst, um den Gruselfaktor zu erhöhen.","sz":9.0,"box":[320.3,599.0,524.1,656.0],"p":47,"i":15,"sec":"ecke-pine-und-5th"},{"t":"card","x":"<b>Der Fahrer ist tot.</b> Es ist schwer zu sagen, woran er letztendlich gestorben ist. Eine sorgfältige Untersuchung zeigt, dass seine Lippen Spuren von Lippenstift aufweisen, die dem Anschein nach von einem Kuss stammen.","sz":null,"k":"yellow","box":[309.3,685.2,541.7,756.6],"p":47,"i":16,"sec":"ecke-pine-und-5th"}],"size":[595.276,841.89]},"48":{"tab":"","blocks":[{"t":"card","x":"<b>Dem Führerschein nach handelt es sich um David Nguyen.</b> Er ist sichtbar wohlhabend, trägt einen teuren Anzug, eine ebensolche Uhr und Schuhe und fährt einen Sportwagen.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,112.9],"p":48,"i":0,"sec":"ecke-pine-und-5th"},{"t":"card","x":"An Davids Händen befinden sich Schmauchspuren. <b>Er hat vor kurzem eine Schusswaffe abgefeuert.</b>","sz":null,"k":"yellow","box":[54.1,122.1,286.6,168.5],"p":48,"i":1,"sec":"ecke-pine-und-5th"},{"t":"card","x":"Anhand der Reifenspuren, des Aufprallverlaufs und Dellen am Auto ergibt die Untersuchung, dass <b>David</b> wenige Augenblicke vor dem Unfall die <b>Kontrolle über das Fahrzeug verloren</b> hat.","sz":null,"k":"yellow","box":[54.1,177.7,286.6,236.4],"p":48,"i":2,"sec":"ecke-pine-und-5th"},{"t":"card","x":"<b>Es ist unmöglich festzustellen, woher das Auto kam.</b> Umfangreiche und lange Nachforschungen mit Hilfe von Überwachungskameras oder magischer Mittel ergeben, dass es von außerhalb der Stadt gekommen ist.","sz":null,"k":"yellow","box":[54.1,245.7,286.6,317.1],"p":48,"i":3,"sec":"ecke-pine-und-5th"},{"t":"card","x":"<b>Einem aufmerksamen Ermittler könnte der Schlamm an Davids Schuhen auffallen.</b> Derselbe Schlamm findet sich im Reifenprofil des Autos. Eine Analyse weist auf eine Herkunft außerhalb der Stadt hin, der Versand an ein Labor könnte mehrere Drehpausen dauern, um Ergebnisse zu erhalten (wenn der Nebel das Labor nicht die Proben verlieren lässt).","sz":null,"k":"yellow","box":[54.1,326.0,286.6,434.9],"p":48,"i":4,"sec":"ecke-pine-und-5th"},{"t":"card","x":"<b>Wenn die Erinnerungen oder der Verstand des Verstorbenen durch magische Mittel zugänglich sind</b>, ist das letzte Bild, an das er sich erinnert, der Anblick Ellie Woodworths, als er sie küsste (ohne zu wissen, dass es sich um ihren Puppen-Klon handelte).","sz":null,"k":"yellow","box":[54.1,444.1,286.6,527.9],"p":48,"i":5,"sec":"ecke-pine-und-5th"},{"t":"card","x":"<b>Jenseits des Nebels</b> steht David Nguyens Geist immer noch unter Schock und <t>wechselt ins Jenseits 3</t> oder ins Nichts. Falls er zu sich kommt, wird er von Ellie Woodworth besessen sein und sie aufsuchen, möglicherweise in der <u>Wohnung der Woodworths.</u> Freiwillig wird er keine Informationen über seine letzten Handlungen herausgeben, und er erinnert sich auch nicht. (Ohne Hilfe eines Risses kann sein Geist nicht mit Ellie interagieren.)","sz":null,"k":"yellow","box":[54.1,537.1,286.6,671.0],"p":48,"i":6,"sec":"ecke-pine-und-5th"},{"t":"card","x":"<b>Jenseits des Nebels</b> verströmt das Gift der Schausteller:innen einen vagen Mythos-Abdruck von antiken Piraten und Plünderern.","sz":null,"k":"yellow","box":[54.1,680.3,286.6,726.6],"p":48,"i":7,"sec":"ecke-pine-und-5th"},{"t":"p","x":"<b>Weiter jenseits des Nebels</b> ist in der zerbrochenen Windschutzscheibe eine kaum merkliche Spur von Bosheit zu erkennen. Es ist unmöglich, sie mit etwas oder jemandem in Verbindung zu bringen, sondern nur mit einer weit entfernten böswilligen Absicht.","sz":10.0,"box":[317.5,59.7,528.3,132.2],"p":48,"i":8,"sec":"ecke-pine-und-5th"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER DAVID NGUYEN</b>","sz":10.0,"box":[309.4,147.1,457.2,169.1],"p":48,"i":9,"sec":"ecke-pine-und-5th"},{"t":"p","x":"Sobald sie den Namen des Opfers wissen, kann das Team weitere Informationen über ihn sammeln.","sz":9.5,"box":[309.0,174.7,522.0,196.7],"p":48,"i":10,"sec":"ecke-pine-und-5th"},{"t":"card","x":"<b>Anwohner:innen können David oder das Auto erkennen</b> und sagen, dass er kürzlich in <u>Rondo‘s Diner oder Shinobi Sushi</u> war.","sz":null,"k":"yellow","box":[309.3,205.9,541.7,252.0],"p":48,"i":11,"sec":"ecke-pine-und-5th"},{"t":"card","x":"<b>David Nguyen ist ein stinkreicher, erfolgreicher Unternehmer Mitte dreißig</b>, Partner bei Orimaka Finance. Sein Erfolg scheint ebenso sehr auf seine Familie wie auf Geschick und harte Arbeit zurückzuführen zu sein.","sz":null,"k":"yellow","box":[309.3,261.2,541.7,332.6],"p":48,"i":12,"sec":"ecke-pine-und-5th"},{"t":"card","x":"<b>Er ist ledig</b> und war auf Dating-Seiten aktiv, nahm an Speed-Dating teil und gab Kontaktanzeigen in Zeitungen auf. Vor zwei Wochen, nach der l<b>etzten Verabredung mit Emma Bailey</b>, einer Flugbegleiterin, die auch im <u>Shinobi Sushi</u> abhängt, endete diese Aktivität.","sz":null,"k":"yellow","box":[309.3,341.9,541.7,425.7],"p":48,"i":13,"sec":"ecke-pine-und-5th"},{"t":"card","x":"Er besitzt eine Luxus-Eigentumswohnung in einem der schicksten Wohnhäuser der Stadt <u>(David Nguyens Wohnung).</u>","sz":null,"k":"yellow","box":[309.3,434.9,541.7,481.2],"p":48,"i":14,"sec":"ecke-pine-und-5th"},{"t":"card","x":"<b>Wenn das Team Zugang zum Leichenschauhaus und/oder zum Bericht des Gerichtsmediziners hat</b>, erfährt es, dass David an Atemstillstand gestorben ist, verursacht durch ein Gift, das er eingenommen oder eingeatmet hat.","sz":null,"k":"yellow","box":[309.3,490.2,541.7,561.6],"p":48,"i":15,"sec":"ecke-pine-und-5th"},{"t":"h","x":"RONDO‘S DINER UND SHINOBI SUSHI","sz":16.0,"box":[333.9,578.4,467.2,611.4],"p":48,"i":16,"skip":true,"sec":"rondo-s-diner-und-shinobi-sushi"},{"t":"ro","x":"Wenn man im Regen an der Ecke Pine Street und 5th steht, bemerkt man zwei überfüllte Lokale auf der gegenüberliegenden Straßenseite. Auf der einen Seite befindet sich Rondo‘s Diner mit seinen roten, von rosa Neonröhren gesäumten Sitznischen. Es sieht aus, als könnte man dort rund um die Uhr fettiges Essen oder Pfannkuchen mit wässrigem Kaffee bekommt. Daneben liegt das Shinobi Sushi. Mit der blauen Neonreklame scheint es für Leute, die sich zu sehr bemühen, gesehen zu werden, gemacht zu sein. Beide Lokale wirken sehr gut besucht, also muss hier jemand etwas gesehen oder gehört haben.","sz":9.0,"box":[317.5,613.8,538.9,774.0],"p":48,"i":17,"sec":"rondo-s-diner-und-shinobi-sushi"}],"size":[595.276,841.89]},"49":{"tab":"","blocks":[{"t":"p","x":"Die beiden Lokale können dem Team helfen, Davids Vergangenheit zu enträtseln und auf die Verbindung zu Pauline und Ellie zu stoßen. Die Woodworths waren sowohl im Diner als auch im Sushi-Laden Stammgäste, und die anderen Stammgäste wissen, wer sie sind und was bei ihnen passiert.","sz":9.5,"box":[53.9,59.9,285.3,131.9],"p":49,"i":0,"sec":"rondo-s-diner-und-shinobi-sushi"},{"t":"card","x":"<b>David Nguyen ist zum ersten Mal bei einem Date im Rondo‘s Diner mit Emma Bailey</b>, einer Grauen Maus von Flugbegleiterin (zur Unfallzeit im <u>Shinobi Sushi),</u> in dieser Gegend. Das Date lief schlecht, weil er nicht aufhörte, Ellie Woodworth anzustarren. Emma erklärte, dass Ellie vergeben und mit Pauline zusammen sei, aber ihn schien das nicht zu stören.","sz":null,"k":"yellow","box":[54.1,139.1,286.6,248.0],"p":49,"i":1,"sec":"rondo-s-diner-und-shinobi-sushi"},{"t":"card","x":"<b>David Nguyen begann Pauline und Ellie zu belästigen</b> und versuchte einige Male, sich den beiden aufzudrängen und mit ihnen zu Abend zu essen. Er machte Ellie in Gegenwart von Pauline unverhohlen Avancen. Sie ließen ihn zunächst höflich abblitzen, aber irgendwann drohte Pauline ihm, ihm wehzutun, wenn er sie nicht in Ruhe ließe. Er verfolgte sie und hielt sich immer häufiger in diesem Teil der Stadt auf.","sz":null,"k":"yellow","box":[54.1,257.2,286.6,391.1],"p":49,"i":2,"sec":"rondo-s-diner-und-shinobi-sushi"},{"t":"card","x":"<b>Es war Emmas Wunsch, sich in Rondo‘s Diner zu verabreden</b>, eine merkwürdige Wahl, da sie normalerweise nicht dorthin geht. Sie hatte nicht vor, in „diesem kitschigen Laden“ zu bleiben, sondern wollte sich dort abholen lassen und in ein schöneres Restaurant gehen, aber dann sah David Ellie.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,150.6],"p":49,"i":3,"sec":"rondo-s-diner-und-shinobi-sushi"},{"t":"card","x":"<b>Die Befragung Emmas ergibt, dass ein mysteriöser Dritter wollte, dass David und Ellie sich treffen.</b> Jemand (Detektiv Holliday), der wusste, dass sie verabredet waren, hinterließ ihr eine Nachricht und versprach, die Miete für den nächsten Monat zu übernehmen, wenn sie zuerst ins Diner gingen. Da sie knapp bei Kasse war, willigte sie ein, und dachte, es handele sich um einen Werbegag. Nach der Verabredung überwies jemand anonym die Miete.","sz":null,"k":"yellow","box":[309.3,159.6,541.7,293.5],"p":49,"i":4,"sec":"rondo-s-diner-und-shinobi-sushi"},{"t":"card","x":"Die Woodworths wohnen weniger als einen Häuserblock entfernt <u>(Wohnung der Woodworths).</u>","sz":null,"k":"yellow","box":[309.3,302.7,541.7,349.1],"p":49,"i":5,"sec":"rondo-s-diner-und-shinobi-sushi"}],"size":[595.276,841.89]},"50":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 2:","sz":14.0,"box":[53.9,69.1,122.1,83.1],"p":50,"i":0,"skip":true,"sec":"schicht-2-ein-gut-geoelter-mechanismus"},{"t":"h","x":"EIN GUT GEÖLTER MECHANISMUS","sz":23.0,"box":[53.9,91.4,218.5,142.4],"p":50,"i":1,"skip":true},{"t":"h","x":"DIE WOHNUNG DER WOODWORTHS","sz":16.0,"box":[78.8,156.0,205.1,189.0],"p":50,"i":2,"skip":true,"sec":"die-wohnung-der-woodworths"},{"t":"ro","x":"Ihr schaut die triste Backsteinfassade hinauf und seht sie. Malerisch steht sie am Fenster und wartet. Regentropfen rinnen über die Fensterscheibe, verzerren leicht ihre Silhouette. Die Mimik verrät, dass sie auf jemanden wartet, der nicht kommt. Die Liebe ihres Lebens? Den toten Mann im Auto? Jemand anderen? Als ihr klingelt, wendet sie sich ruckartig vom Fenster ab, um den Türöffner zu betätigen. Ihr macht euch auf die Enttäuschung in ihren Augen gefasst, wenn sie sieht, dass nur ihr es seid, und auf den größeren Schmerz, den ihr ihr bringt.","sz":9.0,"box":[62.4,191.4,283.8,340.8],"p":50,"i":3,"sec":"die-wohnung-der-woodworths"},{"t":"p","x":"Die Woodworths leben in einem bescheidenen Apartment in einem der wenigen erschwinglichen Wohngebäude der Innenstadt. Ellie Woodworth (Schläferin) ist zu Hause und wartet auf Pauline, die noch nicht von der Arbeit zurück ist und auf keine Nachrichten reagiert. Die Schläferin ist eine hübsche, zierliche junge Frau, die sanft und leise spricht und ein legeres Kleid trägt. Als sich das Team vorstellt und sie erfährt, was mit David passiert ist, bekommt sie Angst, und wandert händeringend auf und ab.","sz":9.5,"box":[53.9,349.8,282.4,471.8],"p":50,"i":4,"sec":"die-wohnung-der-woodworths"},{"t":"card","x":"<b>Pauline ist noch nicht von der Arbeit zurückgekehrt.</b> Sie hat überall Projekte, und Ellie weiß nicht, wo sie heute gearbeitet hat.","sz":null,"k":"yellow","box":[54.1,477.2,286.6,523.6],"p":50,"i":5,"sec":"die-wohnung-der-woodworths"},{"t":"card","x":"<b>Nguyen belästigt sie seit zwei Wochen und macht unangemessene Avancen.</b> Pauline war wütend und wollte ihm eine Lektion erteilen, und da sie die <b>Stärke ihrer Frau</b> (nicht den Ursprung) kennt und eine Eskalation fürchtete, flehte Ellie sie an, ruhig zu bleiben. Sie haben David bei der Polizei angezeigt, die aber nichts unternommen hat. Sie dachten daran, sich juristische Hilfe zu suchen, merkten aber, dass ihr Budget nicht mit Davids mithalten konnte.","sz":null,"k":"yellow","box":[54.1,532.8,286.6,666.7],"p":50,"i":6,"sec":"die-wohnung-der-woodworths"},{"t":"card","x":"<b>Pauline war in letzter Zeit distanziert und vage, was ihre Arbeit angeht.</b> Ellie vermutet, dass es etwas mit Davids Belästigung zu tun hat, und glaubt dazu, dass Pauline ihr etwas verheimlicht. Vielleicht will sie sie mit einem Haus in der Vorstadt überraschen?","sz":null,"k":"yellow","box":[54.1,675.9,286.6,759.7],"p":50,"i":7,"sec":"die-wohnung-der-woodworths"},{"t":"card","x":"Ellies Lippenstift entspricht dem Farbton und der Marke dessen auf David Nguyens Lippen (nur dass er nicht vergiftet ist).","sz":null,"k":"yellow","box":[309.3,54.1,541.7,100.5],"p":50,"i":8,"sec":"die-wohnung-der-woodworths"},{"t":"sh","x":"<b>WOHNUNGSDURCHSUCHUNG</b>","sz":10.0,"box":[309.4,107.8,468.9,117.8],"p":50,"i":9,"sec":"die-wohnung-der-woodworths"},{"t":"p","x":"Für eine gründliche Wohnungsdurchsuchung braucht das Team Ellies Erlaubnis oder muss sich in ihrer Abwesenheit hineinschleichen. Ellie wird wissen wollen, wer die Mitglieder des Teams sind und warum sie sich für den Fall interessieren, ehe sie zustimmt.","sz":9.5,"box":[309.0,123.4,535.2,182.9],"p":50,"i":10,"sec":"die-wohnung-der-woodworths"},{"t":"card","x":"<b>Am Schuhregal der Woodworths befindet sich Schlamm, der mit dem an den Schuhen und Reifen David Nguyens übereinstimmt.</b> Für die Analyse des Schlamms gilt dasselbe wie oben beschrieben.","sz":null,"k":"yellow","box":[309.3,191.5,541.7,262.9],"p":50,"i":11,"sec":"die-wohnung-der-woodworths"},{"t":"card","x":"<b>Zwischen zwei Brettern im Kleiderschrank</b> (Pauline hat das mythische Projekt versteckt) l<b>iegt ein Ordner mit Bauplänen</b> für einen Vergnügungspark am Rande der Stadt, wo sich jetzt der <u>verlassene Rummelplatz</u> befindet.","sz":null,"k":"yellow","box":[309.3,272.2,541.7,343.6],"p":50,"i":12,"sec":"die-wohnung-der-woodworths"},{"t":"h","x":"DETEKTEI HOLLIDAY","sz":16.0,"box":[334.8,378.1,467.5,394.1],"p":50,"i":13,"skip":true,"sec":"detektei-holliday"},{"t":"ro","x":"Holliday hätte kein passenderes Büro wählen können. Das Eckbüro im zweiten Stock, das man über eine schmale Treppe zwischen zwei Geschäften im Erdgeschoss erreicht, blickt auf die darunter liegende Kreuzung. Der Schriftzug auf der Milchglastür, der mächtige Hartholzschreibtisch und die grüne Schreibtischlampe verraten, dass er einer dieser typischen Detektive ist. Das Klappbett, auf dem sich noch die Laken befinden, und die im Aktenschrank versteckte Flasche Whiskey bestätigen diese Einschätzung.","sz":9.0,"box":[317.5,396.5,538.9,535.1],"p":50,"i":14,"sec":"detektei-holliday"},{"t":"p","x":"Die Detektei Holliday befindet sich ein paar Blocks entfernt von der <u>Ecke Pine und 5th.</u> Ist Holliday anwesend, heißt er die SC willkommen und tut hilfsbereit, schweigt aber aus <b>Professionalität</b> zu seinem aktuellen (Verfolgung des Teams und Goldies) oder vergangenen Aufträgen (Profiling anderer Risse, darunter Pauline Woodworth und David Nguyen). Er nutzt die Gelegenheit, um Informationen über das Team zu sammeln und die Mythen der SC zu erkennen. Nur durch Bestechung oder Bedrohung gibt er sein Wissen ganz oder teilweise preis.","sz":9.5,"box":[309.0,544.1,541.4,678.6],"p":50,"i":15,"sec":"detektei-holliday"},{"t":"p","x":"Im Büro Hinweise zu finden wird schwierig, da der altgediente Privatdetektiv alle Beweise <i>Gut versteckt</i> hat. Eine Durchsuchung, wenn er dabei ist, löst seine Aktion <b>Gewieft</b> aus, die ihm <t>aufmerksam 2</t> verleiht.","sz":9.5,"box":[309.0,687.3,531.2,734.4],"p":50,"i":16,"sec":"detektei-holliday"}],"size":[595.276,841.89]},"51":{"tab":"","blocks":[{"t":"card","x":"<b>Eine Telefonnummer, die Holliday vor kurzem angerufen hat, oder eine Briefkastenadresse in seinem Notizblock</b>, könnte das Team zu einer der Schausteller:innen führen und die Verfolgung zum <u>verlassenen Rummelplatz.</u>","sz":null,"k":"yellow","box":[54.1,54.1,286.6,125.6],"p":51,"i":0,"sec":"detektei-holliday"},{"t":"card","x":"<b>Holliday bewahrt eine Kopie aller Profildossiers auf.</b> Etwa zwanzig davon liegen in einem Karton, der in einem Loch in der Wand hinter einem Bücherregal versteckt ist. Darunter sind die Profile Davids, Paulines und Goldies, aber keine Akten über die SC, es sei denn, der Privatdetektiv hatte schon genügend Zeit, um einen Ordner zusammenzustellen.","sz":null,"k":"yellow","box":[54.1,134.8,286.6,243.4],"p":51,"i":1,"sec":"detektei-holliday"},{"t":"card","x":"<b>Die Akten enthalten Details und Fotos aber keine Analyse.</b> Ein Detektiv könnte vermuten, dass Holliday nicht wusste, wonach genau sein Auftraggeber suchte, und deshalb das Leben und besondere Fähigkeiten nur beschrieben hat. Es gibt Hinweise auf die <u>Wohnung der Woodworths</u> und <u>David Nguyens Wohnung.</u>","sz":null,"k":"yellow","box":[54.1,252.6,286.6,349.1],"p":51,"i":2,"sec":"detektei-holliday"},{"t":"card","x":"<b>Davids Profil</b> enthält ein Bild seiner Wohnung, in der Antiquitäten und archäologische Artefakte an den Wänden hängen, darunter ein antikes Schild mit einem Davidstern. Es gibt ein Bild von ihm, wie er in einer Kneipe Gitarre spielt, mit der Notiz: „Als ich aufwachte, war er weg, alle im Zimmer schliefen.“ (eine Anspielung auf König Davids magisches Harfenspiel)","sz":null,"k":"yellow","box":[54.1,358.3,286.6,466.8],"p":51,"i":3,"sec":"detektei-holliday"},{"t":"card","x":"<b>Paulines Profil</b> enthält Bilder, auf denen sie als Riesin auf einer Baustelle arbeitet und eine Palette mit Ziegelsteinen vom Boden in den dritten Stock hebt. Ein Stadtplan zeigt die Standorte ihrer Projekte, die sich alle am Stadtrand befinden. Daneben ist „Stadterweiterung?“ gekritzelt. Zusätzlich gibt es Bilder von ihr und Ellie beim Wandern und Kajakfahren.","sz":null,"k":"yellow","box":[54.1,476.1,286.6,597.6],"p":51,"i":4,"sec":"detektei-holliday"},{"t":"card","x":"<b>Goldies Profil</b> ist ein dickes Bündel mit Polizeiprotokollen über ungelöste Einbrüche. Es gibt Fotos von geschrumpften, aus den Angeln gefallenen Türen und verkohlten Alarmanlagen. Einige heimlich aufgenommene und bezaubernde Porträtfotos verraten die Gefühle des Privatdetektivs für sie.","sz":null,"k":"yellow","box":[54.1,606.5,286.6,703.0],"p":51,"i":5,"sec":"detektei-holliday"},{"t":"h","x":"JEMAND ANDERS?","sz":14.0,"box":[320.3,70.9,408.3,84.9],"p":51,"i":6,"sec":"detektei-holliday"},{"t":"p","x":"Hollidays Karton kann auch das Profil eines bekannten Risses enthalten – einer Nebenfigur, die dem Team am Herzen liegt, eines wiederkehrenden Charakters (wie Officer Das) oder vielleicht sogar einer Nemesis. Das Team muss diese Person warnen, sonst trifft es sie vielleicht auf dem verlassenen Rummelplatz oder findet es tot in einer von Drakes Fallen.","sz":9.0,"box":[320.3,97.4,529.2,190.4],"p":51,"i":7,"sec":"detektei-holliday"},{"t":"h","x":"DAVID NGUYENS WOHNUNG","sz":16.0,"box":[334.8,221.1,517.7,237.1],"p":51,"i":8,"skip":true,"sec":"david-nguyens-wohnung"},{"t":"ro","x":"Um zu David Nguyens Wohnung zu gelangen, muss man auf die andere Seite der Innenstadt, die Seite mit sauberen Straßen und endlosen Versprechungen. Inmitten glänzender Hochhäuser und luxuriöser Hotels liegt ein teuer aussehendes Apartmenthaus mit Parkservice. In der Lobby steht ein hochnäsiger Portier Wache, um unerwünschte Besucher abzuwehren. Er mag wie ein Hund auf der Straße gestorben sein, aber gelebt hat Nguyen wie ein König.","sz":9.0,"box":[317.5,239.5,538.9,356.5],"p":51,"i":9,"sec":"david-nguyens-wohnung"},{"t":"p","x":"Der aufstrebende Finanzberater David Nguyen besaß und bewohnte eine herrliche Wohnung im 30. Stock mit Blick auf das Finanzviertel, nur einen Steinwurf von seinem Büro bei Orimaka Finance, der Firma, deren Miteigentümer er war.","sz":9.5,"box":[309.0,365.5,533.2,425.0],"p":51,"i":10,"sec":"david-nguyens-wohnung"},{"t":"p","x":"Sie enthält einige Hinweise auf den Mythos David Nguyens und seine Besessenheit von Ellie Woodworth. Die Wohnung ist der Fokus für Goldies Jagd nach allen greifbaren Dingen, die David zurückgelassen hat.","sz":9.5,"box":[309.0,433.6,539.2,480.6],"p":51,"i":11,"sec":"david-nguyens-wohnung"},{"t":"sh","x":"<b>IN DIE WOHNUNG GELANGEN</b>","sz":10.0,"box":[309.4,494.3,470.3,504.3],"p":51,"i":12,"sec":"david-nguyens-wohnung"},{"t":"p","x":"Wenn Theresa Nguyen das Team angeheuert hat oder es einen Durchsuchungsbeschluss besitzt (wenn es offiziell Davids Tod untersucht), gelangt es leicht in die Wohnung.","sz":9.5,"box":[309.0,509.8,533.7,556.8],"p":51,"i":13,"sec":"david-nguyens-wohnung"},{"t":"p","x":"Wenn die SC Goldie dabei haben oder ihr folgen, ist es kein Problem, hineinzukommen, aber illegal. Goldie kann gut auf sich aufpassen, doch das Team muss <b>Heimlichkeit</b> einsetzen, um nicht erwischt zu werden.","sz":9.5,"box":[309.0,565.5,540.0,612.6],"p":51,"i":14,"sec":"david-nguyens-wohnung"},{"t":"p","x":"Wenn das Team auf eigene Faust eindringt, müssen sich die SC mit den Sicherheitsmaßnahmen der Wohnung auseinandersetzen. Sie könnten feststellen, dass Goldie dort bereits eingebrochen ist, vielleicht noch da ist und sich um Davids Spinne kümmert (sie ist erst nach Davids Tod eingebrochen, weil sie die schreckliche Neigung hat, zu lange an Tatorten zu bleiben, sodass die Eigentümer sie auf frischer Tat ertappen). Wenn das Team die Polizei alarmiert, werden wahrscheinlich die Beamten Das und Quinn auftauchen.","sz":9.5,"box":[309.0,621.2,537.9,743.2],"p":51,"i":15,"sec":"david-nguyens-wohnung"}],"size":[595.276,841.89]},"52":{"tab":"","blocks":[{"t":"card","x":"<b>IN DER WOHNUNG</b>","sz":null,"k":"yellow","box":[47.5,55.0,165.3,81.5],"p":52,"i":0,"sec":"david-nguyens-wohnung"},{"t":"p","x":"In der Wohnung gibt es zwar teure Gegenstände zu stehlen, aber der Schatz, den Goldie bei David vermutet, ist nirgends zu finden. Goldie wird die Wohnung von oben bis unten durchsuchen, Hinweise finden und zu dem Schluss kommen, dass David sein Vermögen woanders versteckt hat: Dort, von wo er in der Nacht seines Todes zurückkam.","sz":9.5,"box":[53.9,79.2,282.7,163.7],"p":52,"i":1,"sec":"david-nguyens-wohnung"},{"t":"p","x":"Die Durchsuchung kann zu den unten aufgeführten Hinweisen führen, birgt aber das Risiko, Alarm auszulösen oder, was gefährlicher ist, die Aufmerksamkeit von <b>Davids Riesenspinne</b> auf sich zu lenken.","sz":9.5,"box":[53.9,172.4,280.8,219.5],"p":52,"i":2,"sec":"david-nguyens-wohnung"},{"t":"card","x":"<b>An der Wand hängen altertümliche Artefakte: ein Bronzeschild, eine Schleuder und ein blutiger Stein.</b> Auf dem Schild ist der Davidsstern eingraviert (das Davidsschild). Der Blick hinter den Nebel enthüllt eine biblische Schlachtszene, in der Nguyen, der sich hinter diesem Schild versteckt, mit Schleuder und Stein einen riesigen Krieger erschlägt.","sz":null,"k":"yellow","box":[54.1,233.6,286.6,342.4],"p":52,"i":3,"sec":"david-nguyens-wohnung"},{"t":"card","x":"<b>David war besessen von Ellie.</b> Auf dem gläsernen Couchtisch liegen Fotos von ihr, die anscheinend ein Privatdetektiv (nicht Holliday) aufgenommen hat. Am Fenster steht ein Teleskop, das auf die Kreuzung von Pine und 5th St. gerichtet ist (die Wohnung liegt an einer Straße, die die Pine St. fortsetzt).","sz":null,"k":"yellow","box":[54.1,351.6,286.6,447.8],"p":52,"i":4,"sec":"david-nguyens-wohnung"},{"t":"card","x":"<b>David hat Pauline überprüft.</b> In seinem Schrank oder auf seinem Computer sind die Ergebnisse einer Recherche über Woodworth- Bau versteckt, aus denen hervorgeht, dass Pauline an einem großen Projekt auf dem <u>verlassenen Rummelplatz</u> vor der Stadt arbeitet.","sz":null,"k":"yellow","box":[54.1,457.1,286.6,540.9],"p":52,"i":5,"sec":"david-nguyens-wohnung"},{"t":"threat","stars":"★★★","name":"RIESENSPINNE","spectra":"","items":[],"box":[392.0,56.9,422.6,68.9],"p":52,"i":6,"sec":"david-nguyens-wohnung"},{"t":"p","x":"In einer Geschichte hilft eine große Spinne König David, als er vor den Soldaten seines Rivalen, König Saul, flieht. Die Spinne webt ein Netz, das die Höhle, in der sich David versteckt, bedeckt und es aussehen lässt, als ob er diesen Weg nicht hätte gehen können. In der Stadt manifestiert sich das in Form einer riesigen Vertrauten, die David Nguyen treu ergeben ist und seine Wohnung bewacht.","sz":9.0,"box":[316.2,80.0,527.6,173.0],"p":52,"i":7,"sec":"david-nguyens-wohnung"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / VERSCHEUCHEN 5</b>","sz":12.0,"box":[316.3,183.5,501.5,207.5],"p":52,"i":8,"sec":"david-nguyens-wohnung"},{"t":"p","x":"• <b>Riesig</b>: Wenn die Spinne körperlichen Schaden erleidet, sinkt die Zustandsstufe um 2, es sei denn, der Zustand betrifft die gesamte Riesenspinne. • <b>Krabbler</b>: Wenn die Spinne die Szene überraschend betritt, kann die SL eine harte Aktion machen. Außerdem verleiht sie Anwesenden <t>verängstigt 3</t>.","sz":9.0,"box":[316.2,212.0,531.6,281.0],"p":52,"i":9,"sec":"david-nguyens-wohnung"},{"t":"p","x":"• Einen Strahl klebriger Netzflüssigkeit ausspucken (<t>verklebt 3</t>), um ihre Beute zum Naschen zu sich zu ziehen. • Die Beute beißen und Gift injizieren (<t>vergiftet 3</t>). Das Ziel erhält denselben Zustand zu Beginn und Ende jeder folgenden Drehpause, bis die SL entscheidet, dass es das Gift überlebt hat. Heilende Effekte müssen den Zustand nur einmal entfernen.).","sz":9.0,"box":[316.2,290.0,528.9,383.0],"p":52,"i":10,"sec":"david-nguyens-wohnung"},{"t":"p","x":"• Zischend mit pelzigen Beinen nach der Beute stochern","sz":9.0,"box":[316.2,392.0,505.6,413.0],"p":52,"i":11,"sec":"david-nguyens-wohnung"},{"t":"h","x":"DER SPUK","sz":16.0,"box":[333.1,458.2,398.6,474.2],"p":52,"i":12,"skip":true,"sec":"der-spuk"},{"t":"p","x":"Sobald Drake von Holliday genügend Informationen über das Team erhalten hat, kann er versuchen, es in seine Falle zu locken, indem er eine seiner lebensechten, animierten Puppen schickt. Diese Roboter fertigt er nach dem Vorbild von Personen, für die sich die Hauptcharaktere interessieren. Drake ist in seinem Repertoire an Charakteren und Effekten nicht eingeschränkt, aber er ist schlau und weiß, wie er Neugier wecken kann, ohne zu viel zu verraten, so dass er zunächst nur ein Teammitglied ins Visier nimmt, um die Begegnung glaubhafter zu machen.","sz":9.5,"box":[309.0,478.1,538.3,612.6],"p":52,"i":13,"sec":"der-spuk"},{"t":"p","x":"<b>Das Auftauchen des Spuks ist ein cineastischer Moment</b>, der sowohl den betreffenden SC als auch deren Spieler:in täuschen soll. Der Spuk taucht in einer Gasse, im Nebel oder Regen auf, und das in ausreichender Entfernung von der Protagonist:in, so dass die Figur nicht eindeutig zu identifizieren und <t>schwer zu erkennen 3</t> ist. Dann verschwindet er und hinterlässt eine Nachricht, die auf den <u>verlassenen Rummelplatz</u> hinweist. Die Botschaft entspricht deren Wesen: ein Agent bringt einen versiegelten Brief, ein Feuerwesen brennt seine Botschaft in die Wand der Gasse usw.","sz":9.5,"box":[309.0,621.4,538.1,768.3],"p":52,"i":14,"sec":"der-spuk"}],"size":[595.276,841.89]},"53":{"tab":"","blocks":[{"t":"p","x":"Der Spuk kann jeder beliebigen Person bzw. jedem beliebigen Charakter nachempfunden sein, solange es jemand ist, den Drake kennt und es Sinn ergibt, dass diese Person das Team auf den <u>verlassenen Rummelplatz</u> führt. Möglichkeiten:","sz":9.5,"box":[53.9,59.9,281.0,119.4],"p":53,"i":0,"sec":"der-spuk"},{"t":"p","x":"• Eine Hauptfigur aus dem Mythos eines SC • Ein Charakter aus dem persönlichen Leben eines SC, tot oder lebendig • Ein Mitglied einer Organisation oder Gruppe, die der SC sucht • Jemand, der wahrscheinlich über Informationen verfügt, nach denen der SC sucht","sz":9.5,"box":[53.9,125.3,283.9,209.8],"p":53,"i":1,"sec":"der-spuk"},{"t":"p","x":"Versuche, die Mysterien und Identitäten des SC anzuspielen, um ihn in Versuchung zu führen, den Spuk zu verfolgen oder Verblassen/Bruch zu markieren.","sz":9.5,"box":[53.9,215.6,280.4,250.1],"p":53,"i":2,"sec":"der-spuk"},{"t":"p","x":"Der Versuch, den Spuk zu fangen, kann eine Verfolgungsjagd auslösen (<i>Fangen 5</i>), aber der Spuk beginnt mit <t>weit weg 3</t> und wird verschwinden, sobald die SL eine harte Aktion macht (<b>Ihnen etwas verweigern, das sie wollen</b>).","sz":9.5,"box":[53.9,258.8,279.0,318.4],"p":53,"i":3,"sec":"der-spuk"},{"t":"h","x":"SCHICHT 3:","sz":14.0,"box":[53.9,337.7,122.0,351.7],"p":53,"i":4,"skip":true,"sec":"schicht-3-eine-lustige-art-zu-sterben"},{"t":"h","x":"EINE LUSTIGE ART ZU STERBEN","sz":23.0,"box":[53.9,360.0,214.1,411.0],"p":53,"i":5,"skip":true},{"t":"h","x":"VERLASSENER RUMMELPLATZ","sz":16.0,"box":[79.7,424.6,279.0,440.6],"p":53,"i":6,"skip":true,"sec":"verlassener-rummelplatz"},{"t":"ro","x":"Der Wind weht über die düstere Freifläche des alten Rummelplatzes, eine Ansammlung von schäbigen Buden und eingefallenen Zelten. Einst blinkende Schilder hängen mit kaputten Neonröhren und verblassten Schriftzügen schief in ihren Halterungen. Zerrissene, ausgeblichene Zeltplanen flattern im Wind. Ein Riesenrad ragt über einigen Fahrgeschäften, Spielbuden und Kuriositätenshows auf. Auf dem Schild über dem Torbogen steht Lemnos-Kirmes. Es ist keine Menschenseele in Sicht.","sz":9.0,"box":[62.4,443.0,283.8,570.8],"p":53,"i":7,"sec":"verlassener-rummelplatz"},{"t":"p","x":"Der verlassene Rummelplatz war einst die Heimat des erfolgreichen Unternehmens der Familie Lemnos,","sz":9.5,"box":[53.9,579.8,279.9,601.8],"p":53,"i":8,"sec":"verlassener-rummelplatz"},{"t":"p","x":"eines Clans von Sinti und Roma, die im Laufe der Jahre Schausteller:innen aus vielen verschiedenen Ethnien assimilierte. Der Karneval war eine der beliebtesten Attraktionen der Stadt und genoss einen unregulierten Stand außerhalb der Stadtgrenzen.","sz":9.5,"box":[309.0,59.9,539.9,119.4],"p":53,"i":9,"sec":"verlassener-rummelplatz"},{"t":"p","x":"Je erfolgreicher die Familie Lemnos wurde, desto mehr beneideten andere sie. Verwaltungsbeamte begannen die Familie zu drangsalieren und schränkten ihre geschäftlichen Aktivitäten ein, bis der Jahrmarkt bankrott ging. Einige Mitglieder der Familie Lemnos verließen den Rummelplatz und wanderten in die Unterstadt aus, um sich den im Müll wühlenden Außenseitern anzuschließen, während andere ausharrten und durch Mundraub und Kleinkriminalität überlebten. Die Seherin <b>Masilda</b> sagte voraus, irgendwann werde ein Gott kommen, um sie zu führen. Der Rummelplatz war baufällig, verrottete und verblasste, bis eines Tages Maximilian Drake im Rollstuhl auf den Rummelplatz fuhr, ein Ausgestoßener, der sich auf geheimnisvolle Weise zu diesem bizarren Ort hingezogen fühlte.","sz":9.5,"box":[309.0,128.1,541.4,312.6],"p":53,"i":10,"sec":"verlassener-rummelplatz"},{"t":"p","x":"Der Clan, der sich selbst die Lemnos-Schausteller:innen nannte, nahm den Riss des Hephaistos als Gott an und kümmerte sich um ihn. Als Gegenleistung für ihre Dienstwilligkeit lehrte er sie seine von seinem Mythos getragenen Wissenschaften und verbesserte ihre Fähigkeiten, bis sie Marodeure mit Superkräften wurden. Von seinem Mythos berührt erwachten sie als Risse der Sintoi und wurden zu Agent:innen und seiner Familie. Zusammen begannen sie mit der Umsetzung des Plans, Risse in der Stadt zu eliminieren, und bauten den Rummelplatz zu der Todesfalle aus, die er heute ist.","sz":9.5,"box":[309.0,321.3,541.3,455.8],"p":53,"i":11,"sec":"verlassener-rummelplatz"},{"t":"h","x":"AUF DEM RUMMELPLATZ","sz":16.0,"box":[309.0,471.4,473.2,487.4],"p":53,"i":12,"skip":true,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Der Rummelplatz erstreckt sich über eine weite Fläche, dicht bedeckt mit zerfallenen Pavillons und heruntergekommenen Buden und Fahrgeschäften. Alle von Hephaistos auf dem Gelände betriebenen Attraktionen haben eine von drei Funktionen: <b>trennen</b>, <b>locken</b> oder <b>töten</b>. Alle werden vom <u>Kontrollraum</u> aus gesteuert, mit einer Kombination aus weltlicher Technologie (je nach technologischem Zeitalter eures Spiels) und mythischer Mechanomantie (übersteigt die Technolo-","sz":9.5,"box":[309.0,491.4,541.6,600.9],"p":53,"i":13,"sec":"auf-dem-rummelplatz"}],"size":[595.276,841.89]},"54":{"tab":"","blocks":[{"t":"h","x":"VORBEREITUNG DIESER SZENE","sz":14.0,"box":[65.9,62.1,206.7,76.1],"p":54,"i":0,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Nimm dir vor dieser Szene etwas Zeit, um die Fähigkeiten, Mythen, Geheimnisse und Identitäten der SC zu betrachten und für jede einen Köder und eine Todesfalle zu entwerfen, wie unten beschrieben.","sz":9.0,"box":[65.9,88.6,272.1,133.6],"p":54,"i":1,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"gie des Zeitalters und gibt ihr eine magische Wendung, also die geheimnisvolle Magie des griechischen Gottes des Handwerks).","sz":9.5,"box":[53.9,159.1,285.4,193.6],"p":54,"i":2,"sec":"auf-dem-rummelplatz"},{"t":"sh","x":"<b>GRUPPEN IN EINZELPERSONEN AUFTEI- LEN</b>","sz":10.0,"box":[54.3,207.2,274.0,229.2],"p":54,"i":3,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Wenn eine Gruppe den Rummelplatz überquert, löst Drake Folgendes aus der Ferne aus:","sz":9.5,"box":[53.9,234.8,273.4,256.8],"p":54,"i":4,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"• Requisiten fallen in sich zusammenfallen und versperren den Weg, wie der gigantische Hotdog von einem Hotdog-Stand • Eine Plane, die zwischen ihnen herabfällt und sie auf verschiedene Teile eines Pavillons verteilt • Kaputte Drehtüren und -kreuze, die eine Person einlassen, aber gleich danach sperren • Fahrgeschäfte wie ein Karussell, Riesenrad oder Autoscooter, die zum Leben erwachen, sobald die SC sie betreten und sie warten lassen, bis sie wieder aussteigen können.","sz":9.5,"box":[53.9,262.6,284.9,397.1],"p":54,"i":5,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Nichts davon ist wirklich gefährlich und jedes Hindernis zwischen den SC lässt sich umgehen. Wenn das Team darauf besteht, sich wieder zu treffen, müssen sie <b>Ein Risiko eingehen</b>, um die Barriere zu überklettern oder zu überqueren. Ein Fehlschlag könnte zur Folge haben:","sz":9.5,"box":[53.9,403.0,281.7,475.0],"p":54,"i":6,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"• Verletzt werden/stecken bleiben • Sich verirren, woanders herauskommen als erwartet • Auslösen einer Falltür, die zu einer anderen Ebene des Rummelplatzes führt, z. B. zu einem unterirdischen Raum, Servicegang hinter den Zelten usw.","sz":9.5,"box":[53.9,480.8,281.1,540.3],"p":54,"i":7,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Sobald eine Person visuell vom Restteam getrennt ist, gilt sie als verirrt und muss <b>Nachforschungen</b> anstellen, um die anderen Teammitglieder zu finden. Musikanlagen schalten sich ein, wenn das Team versucht, durch Rufen zu kommunizieren. Um seine Beute im Dunkeln zu lassen, hat Drake den Ort so eingerichtet, dass er normale Kommunikation und Peilsender stört (alle technischen Geräte erleiden <t>Störung 5</t>), und er kann sich im Voraus etwas ausdenken, um ihm bekannte Hellsichtkräfte eines Mythos zu bekämpfen.","sz":9.5,"box":[53.9,546.2,285.3,668.2],"p":54,"i":8,"sec":"auf-dem-rummelplatz"},{"t":"sh","x":"<b>IN PERSÖNLICHE TODESFALLEN LOCKEN</b>","sz":10.0,"box":[54.3,681.8,277.5,691.8],"p":54,"i":9,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Wenn sich jemand allein über den Rummelplatz bewegt, wird Drake seine Puppen starten, um dem SC Mysterium, Identität oder andere Motivationen zu entlocken (s. o., <u>Der Spuk).</u> Drake nutzt umfangreiche Spezialeffekte wie Nebel, Rauch, Beleuchtung, Soundeffekte usw., um das Erlebnis realistisch erscheinen","sz":9.5,"box":[53.9,697.3,281.5,769.3],"p":54,"i":10,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"zu lassen. Diese Show soll die Zielperson dazu bringen, dem Köder zu folgen, weg vom Team und in eine separate Bude, einen eigenen Pavillon oder speziellen Bereich des Rummelplatzes.","sz":9.5,"box":[309.0,59.9,535.9,106.9],"p":54,"i":11,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"<b>Beschreibe den Spieler:innen den Köder so, wie du eine gewöhnliche Szene beschreiben würdest</b>, z. B. so, als hätte der SC wirklich eine Vision seines Schutzgeistes oder als fordere ihn ein Informant auf, ihm in einen Pavillon zu folgen. Durch Drakes Verhöhnung von Magie-, Fantasie- und Fabelwesen sehen alle Puppen lediglich ein wenig übertrieben aus.","sz":9.5,"box":[309.0,115.7,538.4,200.1],"p":54,"i":12,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Hier einige Hinweise für misstrauische SC, die <b>Nachforschungen</b> darüber anstellen, was sie sehen:","sz":9.5,"box":[309.0,208.8,532.5,230.9],"p":54,"i":13,"sec":"auf-dem-rummelplatz"},{"t":"card","x":"Alles <i>scheint</i> real. Warum hast du nur das Gefühl, dass sich jemand über dich lustig macht?","sz":null,"k":"yellow","box":[309.3,250.6,541.7,284.3],"p":54,"i":14,"sec":"auf-dem-rummelplatz"},{"t":"card","x":"Jenseits des Nebels gibt es nur legendäre Maschinen und das Geräusch eines Hammers, der auf einen Amboss schlägt.","sz":null,"k":"yellow","box":[309.3,293.5,541.7,339.8],"p":54,"i":15,"sec":"auf-dem-rummelplatz"},{"t":"card","x":"Wesen, die mit bloßem Auge mythisch erscheinen, wirken jenseits des Nebels nicht so.","sz":null,"k":"yellow","box":[309.3,349.1,541.7,382.8],"p":54,"i":16,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Sehr misstrauische SC können <b>Das Blatt wenden</b>, um sich auf das Kommende vorzubereiten.","sz":9.5,"box":[309.0,395.1,536.4,417.1],"p":54,"i":17,"sec":"auf-dem-rummelplatz"},{"t":"sh","x":"<b>DAS TÖDLICHE FINALE</b>","sz":10.0,"box":[309.4,430.7,434.6,440.7],"p":54,"i":18,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Drake ist Meister der Maschinen und will beweisen, dass Menschen im Allgemeinen und Risse im Besonderen nur eine andere Art von Maschinen sind. Sobald er herausgefunden hat, wie jemand tickt, nutzt er dessen größten Wunsch oder schlimmste Angst, um ihn in die Falle zu locken.","sz":9.5,"box":[309.0,446.3,540.6,518.3],"p":54,"i":19,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Wenn eine Person ihren Pavillon, Bude usw. betritt, sieht sie ein Spektakel, das sorgfältig darauf abzielt, ihre tiefsten mythischen Fragen anzusprechen, z. B.:","sz":9.5,"box":[309.0,527.0,530.4,561.5],"p":54,"i":20,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"• Wenn sie aus einem anderen Reich kommt, z. B. der Hölle oder einem verzauberten Wald, wird die Falle so aussehen. • Wenn sie das Produkt eines Experiments war, könnte sie ein geheimes Labor entdecken und vermuten, dass der Ursprung ihrer Kräfte dort liegen könnte. • Wenn sie auf der Suche nach jemandem oder etwas war, würde die betreffende Person oder der Gegenstand genau dort sein (natürlich als animierte Puppe).","sz":9.5,"box":[309.0,567.3,540.2,689.3],"p":54,"i":21,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Der Zweck der Show ist es, das Ziel in den Mittelpunkt des Raumes zu locken, wo eine spezielle Falle wartet.","sz":9.5,"box":[309.0,700.8,537.6,722.8],"p":54,"i":22,"sec":"auf-dem-rummelplatz"}],"size":[595.276,841.89]},"55":{"tab":"","blocks":[{"t":"p","x":"Löse die Falle als weiche Aktion aus (es gab genug Vorwarnungen), und der SC erhält einen Zustand der Stufe 5, der speziell seine Fähigkeiten negieren soll:","sz":9.5,"box":[53.9,59.9,286.0,94.4],"p":55,"i":0,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"• Einen übernatürlich schnellen Riss trifft eine Kette von Explosionen, die tausend scharfe Speere um ihn herum abfeuern, so dass er auf sie zuläuft, wohin er auch rennt (<t>aufgespießt aus allen Richtungen 5</t>).","sz":9.5,"box":[53.9,105.9,282.0,152.9],"p":55,"i":1,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"• Ein körperlich unbesiegbarer Riss könnte in einen Tank mit geschmolzenem Panzerstahl fallen, der dann sofort abkühlt (<t>in Stahl eingeschlossen 5</t>).","sz":9.5,"box":[53.9,161.6,272.5,196.1],"p":55,"i":2,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"• Ein Riss, der körperlos werden kann, wird von magischen Fesseln behindert (<t>materialisiert 5</t>), bevor ihn dann ein Eisengewicht zerquetscht (<t>zerquetscht 5</t>).","sz":9.5,"box":[53.9,204.8,281.5,239.3],"p":55,"i":3,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Die SC können <b>Sich der Gefahr stellen</b>, wenn ihre Spieler:innen erklären, wie sie die Todesfalle umgehen. Es gelten nur Kräfte, die für diese Art der Flucht relevant sind. Alternativ dazu können die SC <b>Jetzt reicht’s!</b> und ein Opfer ohne Wiederkehr bringen, um der Falle zu entgehen, sich zu befreien oder zu heilen.","sz":9.5,"box":[53.9,245.1,281.1,317.1],"p":55,"i":4,"sec":"auf-dem-rummelplatz"},{"t":"sh","x":"<b>NACH AUSLÖSUNG DER FALLE</b>","sz":10.0,"box":[309.4,62.8,472.7,72.8],"p":55,"i":5,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Solange noch andere Risse auf dem Rummelplatz unterwegs sind (außer Drake und den Schausteller:innen), lässt Drake kampfunfähige Risse zu sich in den <u>Kontrollraum</u> bringen. Er will etwas beweisen, und es befriedigt ihn nicht, nur seinen Anhänger:innen zu predigen. Darum hält er die kampfunfähigen Ziele am Leben, um ihnen zu zeigen, wie er den Rest ermordet. Wenn du möchtest und es in eure Gruppe passt, wird die letzte ausgelöste Falle einen Stufe-6-Zustand verursachen, woraufhin Drake sein bewusstloses Publikum töten oder loswerden wird.","sz":9.5,"box":[309.0,78.3,537.0,212.8],"p":55,"i":6,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"SC, die ihre persönliche Falle überlebt haben, sind sich nun der Situation bewusst und können alle weiteren Köder ignorieren und andere warnen (wenn sie sie finden oder mit ihnen kommunizieren können). Sie können den Rummelplatz ohne Ablenkungen erforschen. Drake verschwendet keine Zeit mehr mit dem Versuch, einen solchen SC zu ködern. Stattdessen schickt er die Schausteller:innen los, um den Job zu erledigen.","sz":9.5,"box":[309.0,221.5,539.3,318.5],"p":55,"i":7,"sec":"auf-dem-rummelplatz"}],"size":[595.276,841.89]},"56":{"tab":"","blocks":[{"t":"h","x":"GOLDIES FALLE","sz":14.0,"box":[65.2,61.0,135.7,75.0],"p":56,"i":0,"sec":"auf-dem-rummelplatz"},{"t":"p","x":"Goldie kommt auf dem Rummelplatz und sucht dort nach Davids Schatz. In einem der Pavillons befindet sich eine großzügige Wohnung, die der David Nguyens in der Innenstadt ähnlich ist. Seltsamerweise stehen dort drei dampfende Schüsseln Brei auf einem schönen, modernen Esstisch aus Glas, drei moderne Stühle aus der Mitte des Jahrhunderts in verschiedenen Größen auf einem Teppich aus weißem Bärenfell und drei unterschiedlich harte Betten. Da Goldie ihren eigenen Mythos nicht gut kennt, weiß sie nicht, was sie davon halten soll. Es weckt ihre Neugierde auf eine Art, die sie sich nicht erklären kann. Nachdem sie alles durchprobiert hat, findet sie in dem bequemsten Bett eine Tasche voller Geld. Zufrieden wie nie zuvor und unter dem Einfluss der Schlaftabletten, die in die dritte Schüssel Brei gemischt waren, schläft sie ein, die Tasche im Arm, und wacht nicht mehr auf. Das Bett ist so ausgestattet, dass es sie mit einem Stromschlag tötet, wenn sie den Brei nicht isst, es sei denn, jemand tut etwas, um das alles zu verhindern.","sz":9.0,"box":[65.2,87.5,272.6,336.5],"p":56,"i":1,"sec":"auf-dem-rummelplatz"},{"t":"h","x":"NACHFORSCHUNGEN AUF DEM VERLASSENEN RUMMELPLATZ","sz":16.0,"box":[53.9,379.2,255.6,412.2],"p":56,"i":2,"skip":true,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"p","x":"Wenn die SC herausgefunden haben, dass die Köder nicht halten, was sie versprechen und ihre Aufmerksamkeit auf andere Dinge richten, können sie viele Geheimnisse aufdecken:","sz":9.5,"box":[53.9,416.1,274.4,463.1],"p":56,"i":3,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"card","x":"Am Rande des Platzes gibt es einen Bereich mit falschen Steinbauten und Palmen, der wie eine biblische Kulisse aussieht. <b>Der Schlamm hier entspricht demjenigen an Paulines Stiefeln und Davids Schuhen und Autoreifen.</b>","sz":null,"k":"yellow","box":[54.1,470.0,286.6,541.4],"p":56,"i":4,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"card","x":"Hinter einem Steinhaus ist ein <b>großkalibriger Revolver</b> versteckt. In der Trommel sind fünf (von sechs) Patronen. Hieraus stammt die Kugel, die Pauline Woodworth tötete. Sie passt zu den Schmauchspuren an Davids Händen.","sz":null,"k":"yellow","box":[54.1,550.7,286.6,622.1],"p":56,"i":5,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"card","x":"In der Mitte der biblischen Szenerie befindet sich ein Bereich aufgewühlter Erde, groß genug für eine Riesin. Wenn man hier gräbt, findet man die <b>riesige Leiche Pauline Woodworths</b>. Eine Kugel zwischen den Augen hat sie getötet.","sz":null,"k":"yellow","box":[54.1,631.0,286.6,715.1],"p":56,"i":6,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"card","x":"<b>Jenseits des Nebels</b> fand hier ein Mord statt, mit der Vision einer Riesin, die zu Boden stürzte, während die Erde bebte.","sz":null,"k":"yellow","box":[54.1,724.0,286.6,770.4],"p":56,"i":7,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"card","x":"Das Innere eines der Pavillons sieht aus wie ein Königspalast. Hier steht eine lebensgroße Puppe, die aussieht wie Ellie. Ihr Lippenstift, der mit dem Ellies identisch ist, ist abgeblättert, und die Lippen sind verätzt <b>durch das gleiche Gift, das David Nguyen getötet hat</b>.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,138.0],"p":56,"i":8,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"card","x":"Elektrische Leitungen und Antennen weisen auf ein unscheinbares, hohes Gerüst in der Mitte des Geländes hin, das von Wellblech und Lichtern, Requisiten und Schildern bedeckt ist. Hier muss sich der <u>Kontrollraum</u> befinden.","sz":null,"k":"yellow","box":[309.3,147.2,541.7,218.6],"p":56,"i":9,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"card","x":"<b>Jenseits des Nebels</b> führt die Suche nach dem Schöpfer der Puppen oder der Jahrmarktsmaschinen zum <u>Kontrollraum,</u> der sich lodernd als rostiger Eisenturm, aus dem geschmolzenes Metall quillt, vom Horizont abhebt.","sz":null,"k":"yellow","box":[309.3,227.5,541.7,298.9],"p":56,"i":10,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"card","x":"SCHAUSTELLER:INNEN VON LEMNOS","sz":null,"k":"yellow","box":[297.2,307.3,556.1,337.2],"p":56,"i":11,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"p","x":"Die Schausteller:innen von Lemnos leben seit Jahren auf dem verlassenen Rummelplatz, wo sie sich nach dem Zusammenbruch ihres Kirmesimperiums mit Plünderungen und Diebstählen über Wasser halten. Aufgrund ihres jahrelangen Lebens am Rande der Gesellschaft hat Drakes Mythos sie berührt und sie zu den Sintoi gemacht, einem fahrenden Volk von Räuber:innen, Pirat:innen und Plünder:innen, die Hephaistos nach seinem Sturz vom Olymp zum Leben erweckten und anbeteten. Heute dienen sie als Helfer:innen und Wächter:innen hinter den Kulissen.","sz":9.5,"box":[309.0,339.4,536.0,473.9],"p":56,"i":12,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"p","x":"Sie respektieren Ausgestoßene, soziale Außenseiter:innen und Menschen, die auf sich allein gestellt sind, haben aber eine Abneigung gegen feine Pinkel aus der Großstadt und konformistische Mitglieder der Mehrheitsgesellschaft (die sich schon einmal gegen sie gewandt haben). Sie mögen keine Soziopath:innen ohne Respekt vor anderen und ohne familiäre Tradition und Kodex. Im Moment glauben sie ihrem Meisters, dass Risse Missgeburten sind, Frevel wider die Naturgesetze, und beteiligen sich bereitwillig daran, die „Teufelsbrut“ der Stadt auszurotten. Die Schausteller:innen könnten sich in einem Dilemma wiederfinden, wenn ein Riss, den sie für einen gesellschaftlichen Außenseiter halten, sie um Hilfe bittet oder wenn jemand ihnen die Wahrheit über Risse eröffnet.","sz":9.5,"box":[309.0,482.6,540.9,667.1],"p":56,"i":13,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"p","x":"Die Schausteller:innen sind oft in Arbeitskleidung zu sehen: verschmierte Pullover, zerrissene Jeans und Wollmütze. Viele haben ein schräges, ungepflegtes Äußeres und werfen Stadtbewohner:innen, die sie anstarren, bedrohliche Blicke zu. Ihre Werkzeuge glühen rot wie Metall aus dem Ofen, wenn sie mit <b>Mechanomantie</b> die Magie des Hephaistos kanalisieren.","sz":9.5,"box":[309.0,675.7,536.6,760.4],"p":56,"i":14,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"}],"size":[595.276,841.89]},"57":{"tab":"","blocks":[{"t":"threat","stars":"★★","name":"SCHAUSTELLER:INNEN VON LEMNOS","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 3 / BE- DROHEN 3 / UMDREHEN 5","items":["<b>Raues Äußeres</b>: Wenn in einer Szene zum ersten Mal eine Schausteller:in von Lemnos auftritt, erhalten feine Pinkel aus der Großstadt oder Konformist:innen <t>Angst 2</t>. Erhalten die Schausteller:innen einen sozialen, emotionalen oder mentalen Zustand erhält, sinkt die Stufe um 1.","<b>Mechanomantie</b>: Einmal pro Szene kann eine Schausteller:in als Aktion Bewegung (oder jederzeit als harte) ein Fahrgeschäft, Bude, Todesfalle oder eine andere Maschine, die kaputt ist oder kaumfunktioniert, reparieren. Sie entfernt negativen Zustände und stellt ausgebrannte Schwächen her.","Ein Fahrgeschäft zur Ablenkung starten (vorübergehend <t>abgelenkt 2</t>) oder den Weg versperren, während die Schausteller:innen entkommen (<b>Ihnen etwas verweigern etwas, das sie wollen</b>)","Eine Maschine durch Berührung dazu bringen, jemanden anzugreifen (<t>Schlag 2</t> oder <t>Stromstoß 2</t>)","Gewalttätig werden und mit einem Taschenmesser, Schraubenzieher oder einer zerbrochenen Flasche auf jemanden einstechen (<t>Blutung 2</t>)","Aufmerksam vor sich hin starren und sich mit einem Werkzeug in die Handfläche schlagen"],"box":[246.5,81.5,266.9,93.5],"p":57,"i":0,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"p","x":"Einzelne Schausteller:innen sind inzwischen selbst Risse der legendären Versionen traditioneller Rummelplatzattraktionen. Drakes Wissenschaft hat ihre Fähigkeiten verbessert. Vier Schausteller:innen dienen als persönliche Wache und befolgen Befehle aufs Wort.","sz":9.5,"box":[53.9,456.8,286.2,516.3],"p":57,"i":1,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"p","x":"• <b>Yulanda, die Frau mit dem eisernen Kiefer</b>, erhielt tatsächlich ein Kieferimplantat aus Schmiedeeisen.","sz":9.5,"box":[53.9,527.8,279.7,562.3],"p":57,"i":2,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"p","x":"• <b>Mariush, die menschliche Kanonenkugel</b>, hat spezielle feurige Stiefel und einen unzerbrechlichen Helm, und kann sich selbst auf seine Feinde schießen.","sz":9.5,"box":[53.9,571.0,281.8,618.0],"p":57,"i":3,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"p","x":"• <b>Ismail, dem Feuerschlucker</b>, hat einige flammender Krummsäbel von Drake erhalten, die er in seinem Bauch aufbewahren und auf seine Feinde werfen kann. Die Schwerter fliegen zurück in seine Hand (oder in seinen Mund).","sz":9.5,"box":[53.9,626.6,275.6,686.1],"p":57,"i":4,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"p","x":"• <b>Bartley, der Kunstschütze</b>, erhielt ein Paar Pistolen, denen nie die Munition ausgeht.","sz":9.5,"box":[53.9,694.8,275.5,716.8],"p":57,"i":5,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"}],"size":[595.276,841.89]},"58":{"tab":"","blocks":[{"t":"h","x":"YULANDA,","sz":12.0,"box":[62.4,83.4,112.6,95.4],"p":58,"i":0,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"threat","stars":"★★★","name":"DIE FRAU MIT DEM EISERNEN KIEFER","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / UM- DREHEN 6","items":["<b>Unglaubliche Akrobatik</b>: Wenn Yulanda einen Zustand erleidet, dem sie ausweichen kann, reduziert sich dessen Stufe um 2.","<b>Selbstdisziplin</b>: Wenn Yulanda einen sozialen, emotionalen oder mentalen Zustand erleidet, reduziert sich dessen Stufe um 1.","In einem Zirkuszelt oder an hohen Bauwerken Akrobatik vorführen, jemanden packen und in die Luft werfen (<t>Knochenbruch 3</t>) oder an einem Seil aufhängen (<t>aufgehängt 3</t>)","Mit ihren eisernen Kiefer jemanden (<t>Trümmerbruch 4</t>) oder etwas (<t>zerschmettert 4</t>) beißen","Fesseln durchbeißen (bis zu 3 Fesselungsstufen bei sich oder anderen entfernen)","Purzelbäume schlagen"],"box":[245.8,97.3,276.4,109.3],"p":58,"i":1,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"h","x":"BARTLEY, DER KUNSTSCHÜTZE ★★★","sz":12.0,"box":[62.4,428.1,247.7,444.2],"p":58,"i":2,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / UM- DREHEN 6</b>","sz":12.0,"box":[62.4,452.7,266.8,476.7],"p":58,"i":3,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"p","x":"• <b>Schnelles Ziehen</b>: Bartley trifft Angreifende zuerst mit <t>Schuss 3</t>. • <b>Kontrollierter Querschläger, Gezielter Schuss</b>: Wenn sich SC <b>Der Gefahr stellen</b> oder gegen Bartleys Feuer <b>Das Blatt wenden</b>, können sie keine Stärken oder Momentum von Deckung oder Rüstung nutzen, außer sie bieten vollständigen Schutz. • <b>Scharfschütze</b>: Wenn Bartley die Szene betritt, gib ihm <t>zielen 2</t>.","sz":9.0,"box":[62.4,481.2,277.4,586.2],"p":58,"i":4,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"p","x":"• Mehrere Schüsse auf ein einzelnes oder auf mehrere Ziele abgeben (dreimal <t>Fleischwunde 2</t>) • Mit einem Trickschuss etwas Schweres lösen und auf jemanden fallen lassen (<t>behindert 2</t>, <t>liegend 2</t> oder <b>Die Dinge richtig kompliziert machen</b>, was SC normalerweise zwingt, <b>Ein Risiko einzugehen</b>)","sz":9.0,"box":[62.4,595.2,275.4,664.3],"p":58,"i":5,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"p","x":"• Beide Revolver um die Zeigefinger wirbeln lassen","sz":9.0,"box":[62.4,673.2,267.1,682.2],"p":58,"i":6,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"h","x":"MARIUSH,","sz":12.0,"box":[317.5,83.1,369.0,95.1],"p":58,"i":7,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"threat","stars":"★★★","name":"DIE MENSCHLICHE KANONENKUGEL","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / UM- DREHEN 6","items":["<b>Kinetische Energie absorbieren</b>: Wenn Mariush einen physischen Stoß erleidet, absorbiert sein Helm diesen. Er wandelt ihn in einen temporären <t>Geschwindigkeits</t>-Zustand der gleichen Stufe um.","<b>Olympische Kopfbedeckung</b>: Wenn er einen geistigen Zustand erhält, reduziert sich die Stufe um 2.","Sich auf jemanden oder etwas stürzen (<t>Knochenbruch 3</t> oder <t>zerbrochen 3</t>; mit einem <t>Geschwindigkeits</t>-Zustand erhöht dies entweder die Stufe des <t>zerbrochen</t>-Zustands oder der Versuch, <b>Sich der Gefahr zu stellen</b>, wird schwerer)","Seine Stiefel zünden und unsicher ein paar Zentimeter über dem Boden levitieren"],"box":[496.9,97.0,527.5,109.0],"p":58,"i":8,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"},{"t":"threat","stars":"★★★","name":"ISMAIL, DER FEUERSCHLUCKER","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / UM- DREHEN 6","items":["<b>Flammenden Säbelwirbel</b>: Ismails magische Säbel können fast jeden Nahkampfangriff oder Projektile parieren, einschließlich Kugeln, Energiestrahlen und magische Geschosse. Wenn Ismail einen Zustand parieren kann, reduziert sich die Stufe um 2.","<b>(Fast) immun gegen Feuer</b>: Wenn Ismail einen Hitze- oder Feuerzustand erleidet, reduziert sich seine Stufe um 4.","<b>Ich kenne diesen Trick</b>: Wenn Ismail die Szene betritt, gib ihm <t>aufmerksam 2</t>.","Krummsäbel, die zurückkehren, mehrfach auf mehrere Ziele werfen (<t>versengender Schnitt 2</t>, viermal)","Feuer in einem Kegel vor sich spucken (<t>großflächige Verbrennungen 3</t>)","Jemandes Aufmerksamkeit mit der Jonglage der flammenden Krummsäbel erhalten (<t>fasziniert 3</t>)","Einen Krummsäbel um Verbündete schweben lassen, der Angriffe pariert (negiert bis zu drei Stufen eingehender Angriffe auf diese Verbündete)","Einen weiteren brennenden Krummsäbel aus dem Mund ziehen"],"box":[475.4,405.3,506.0,417.3],"p":58,"i":9,"sec":"nachforschungen-auf-dem-verlassenen-rummelplatz"}],"size":[595.276,841.89]},"59":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 4:","sz":14.0,"box":[53.9,61.9,122.1,75.9],"p":59,"i":0,"skip":true,"sec":"schicht-4-wie-menschen-ticken"},{"t":"h","x":"WIE MENSCHEN TICKEN","sz":23.0,"box":[53.9,84.2,283.4,107.2],"p":59,"i":1,"skip":true},{"t":"h","x":"DER KONTROLLRAUM","sz":16.0,"box":[79.7,120.8,220.7,136.8],"p":59,"i":2,"skip":true,"sec":"der-kontrollraum"},{"t":"p","x":"Drakes Kontrollraum liegt im Herzen des Jahrmarkt- Labyrinths in einem behelfsmäßigen Turm aus Gerüstbauteilen und Wellblech, der von oben bis unten mit Schildern der verschiedenen Fahrgeschäfte und Attraktionen des Jahrmarkts bedeckt ist. Wenn die SC sie noch nicht aus dem Verkehr gezogen haben, wird die Leibgarde den Kontrollraum bis zum Ende verteidigen, während die übrigen auf dem Rummelplatz zusehen.","sz":9.5,"box":[53.9,140.7,284.7,237.7],"p":59,"i":3,"sec":"der-kontrollraum"},{"t":"p","x":"Der dunkle, enge Raum ist von Wand zu Wand mit Überwachungsgeräten wie Bildschirmen und Displays ausgestattet, die es Drake ermöglichen, alles mitzubekommen, was auf dem Rummelplatz passiert. Dort sitzt das wahnsinnige Genie in seinem motorisierten Rollstuhl, überwacht die Fallen, stimmt sie perfekt ab und entwirft Pläne für neue.","sz":9.5,"box":[53.9,246.4,279.8,330.9],"p":59,"i":4,"sec":"der-kontrollraum"},{"t":"p","x":"Masilda, die Tarot-Deuterin und Älteste der Schausteller:innen, hilft Drake, die Informationen von Detektiv Holliday zu interpretieren und zu entschlüsseln und ist ebenfalls im Kontrollraum. Sie beobachtet mit Vergnügen, wie die Fallen der leichtgläubigen Opfer zuschnappen. Solange es sich um dreckige Stadtbewohner handelt, ist es ihr egal. Bricht Chaos aus, wird sie versuchen, sich unbemerkt davonzuschleichen.","sz":9.5,"box":[53.9,339.6,284.5,436.6],"p":59,"i":5,"sec":"der-kontrollraum"},{"t":"sh","x":"<b>DIE REDE</b>","sz":10.0,"box":[54.3,450.2,105.3,460.2],"p":59,"i":6,"sec":"der-kontrollraum"},{"t":"p","x":"Drake hat ein Anliegen: Er möchte, dass jemand die Genialität seines Plans versteht und bestätigt, dass er das Wesen der Risse so dekonstruiert hat, wie er es mit aufziehbaren Spielzeug-Affen tun würde. Wenn er wie oben beschrieben einen kampfunfähigen Riss gefangen nimmt und ihn zwingt, zuzusehen, wie seine Freund:innen seinen Fallen zum Opfer fallen, wird er ihn mit den Details seines brillanten Plans und der mechanistischen Philosophie zuquatschen. Dies könnte eine Gelegenheit für SC sein, andere als körperliche Fähigkeiten einzusetzen, um zu entkommen oder Drake davon abzuhalten, mit dem Töten fortzufahren.","sz":9.5,"box":[53.9,465.7,284.4,612.7],"p":59,"i":7,"sec":"der-kontrollraum"},{"t":"sh","x":"<b>KAPITULATION?</b>","sz":10.0,"box":[54.3,626.4,144.3,636.4],"p":59,"i":8,"sec":"der-kontrollraum"},{"t":"p","x":"Drake ist eher intrigantes Superhirn als ein Schurke, der aktiven Kampf sucht. Er ist ein mächtiger Riss und hat die Oberkörpermuskeln eines göttlichen Schmieds, aber es fehlten ihm Courage und Motivation für eine körperliche Auseinandersetzung. Wenn sich das Blatt gegen ihn wendet und je nachdem, wie er seine Chancen einschätzt, wird er verschiedene Taktiken wählen. Berücksichtige auch cineastische Gesichtspunkte, z. B. ob die Geschichte schon genug Kämpfe hatte usw.","sz":9.5,"box":[53.9,641.9,285.0,751.4],"p":59,"i":9,"sec":"der-kontrollraum"},{"t":"p","x":"• Wenn er glaubt, dass das Team ihn verschonen wird, könnte Drake sich ergeben. Er weiß, dass kein normales Gefängnis ihn lange halten kann (Metall beugt sich), und könnte bald wieder frei sein.","sz":9.5,"box":[309.0,59.9,540.6,106.9],"p":59,"i":10,"sec":"der-kontrollraum"},{"t":"p","x":"• Wenn er glaubt, dass das Team die getöteten Risse rächen will, versucht er zu fliehen, indem er sich durch einen vertikalen Schacht in einen umgebauten Fluchtwagen stürzt (<i>Fangen 5</i>). Das Team muss ihn irgendwie an der Flucht zu hindern.","sz":9.5,"box":[309.0,115.6,540.4,175.1],"p":59,"i":11,"sec":"der-kontrollraum"},{"t":"p","x":"• Wenn das Team schon ziemlich ausgepowert ist, kann Drake eine von ihm geschaffene Rüstung anlegen und sich selbst als <b>Der Mechanist</b> bezeichnen (er ist ein Nerd). Dieses rostrote Exoskelett ermöglicht es ihm, zu laufen und Schläge einzustecken. Er unternimmt einen letzten Versuch zu beenden, was er begonnen hat und wird das Team zu töten.","sz":9.5,"box":[309.0,183.8,538.4,268.3],"p":59,"i":12,"sec":"der-kontrollraum"},{"t":"p","x":"Selbst wenn er besiegt wird, hält Drake seine Rede, nur wird sie verbittert und hasserfüllt klingen. Er erklärt, wie Konzepte wie „Magie“ und „Götter“ den Plänen der „wahren“ logischen Denker immer einen Strich durch die Rechnung machen. Wie satt er das hat wird er an jedem auszulassen, der ihm zuhört – sogar an den Polizisten Das und Quinn, die ihn ins Gefängnis begleiten.","sz":9.5,"box":[309.0,274.1,541.4,358.6],"p":59,"i":13,"sec":"der-kontrollraum"},{"t":"p","x":"Wenn das Team Drake befragt, was ihn dazu gebracht hat, zu so drastischen Methoden für seine Philosophie zu greifen, wird er seine Geschichte erzählen und den Namen des Psychiaters nennen, der ihm geholfen hat, mit seiner Behinderung fertig zu werden: <b>Dr. Archibald Tennant von einer Gemeinschaft namens Heilung für die Gebrochenen.</b>","sz":10.0,"box":[317.5,374.4,531.6,471.9],"p":59,"i":14,"sec":"der-kontrollraum"},{"t":"p","x":"Von Drakes Handy wurde immer nur eine Nummer angerufen: die Hotline von Heilung für die Gebrochenen. Er wollte immer mit Dr. Archibald Tennant sprechen.","sz":10.0,"box":[317.5,492.4,524.6,539.9],"p":59,"i":15,"sec":"der-kontrollraum"},{"t":"p","x":"Drake trägt ein Pillenfläschchen mit einem Antidepressivum bei sich, laut Aufkleber von Dr. Archibald Tennant verschrieben. Die Pillen enthalten Spuren von Glaspulver, was höchstwahrscheinlich auf eine verunreinigte Produktionsumgebung zurückzuführen ist.","sz":10.0,"box":[317.5,560.4,531.1,632.9],"p":59,"i":16,"sec":"der-kontrollraum"}],"size":[595.276,841.89]},"60":{"tab":"","blocks":[{"t":"threat","stars":"★★★★","name":"DER MECHANIST","spectra":"AUSSERBETRIEBNAHME 5 / HEILUNG VON SEINEM HASS 6","items":["<b>Hasserfüllt</b>: Wenn der Mechanist den Schauplatz betritt, erhält er <t>hasserfüllt 2</t>. Dies gilt für alle Versuche, ihn zu zur Einsicht zu bringen oder ihn von seinem Hass auf Risse zu heilen.","<b>Olympisches Exoskelett</b>: Wenn die Mechanist- Rüstung einen physischen Zustand oder einen der Unterwerfung erhält, reduziert sich ihre Stufe um 2.","Mechanomantisch eine Waffe erschaffen, die den Fähigkeiten eines Risses entgegenwirkt (was einen Zustand der Stufe 3 verleiht, ihn aber wegen Verwendung von Magie <t>in Verlegenheit 1</t> bringt)","Mechanomantisch das Exoskelett reparieren (jeden Zustand zur <i>Außerbetriebnahme</i> um 2 reduzieren, aber wegen der Magie <t>in Verlegenheit 1</t>)"],"box":[147.8,57.5,188.6,69.5],"p":60,"i":0,"sec":"der-kontrollraum"},{"t":"card","x":"<u>ABSPANN</u>","sz":null,"k":"yellow","box":[44.4,336.4,165.3,361.7],"p":60,"i":1,"sec":"der-kontrollraum"},{"t":"p","x":"Im Folgenden findest du einige Fragen, die du dir stellen solltest, und Punkte, die es beim Abschluss dieses Falles zu bedenken gilt:","sz":9.5,"box":[53.9,376.2,282.3,410.7],"p":60,"i":2,"sec":"der-kontrollraum"},{"t":"p","x":"• Haben alle Mitglieder des Teams und alle Nebendarsteller:innen Drakes Falle überlebt? Wenn nicht, wie gehen die überlebenden Mitglieder mit dem Verlust einer Freund:in um? Welche Emotionen löst das aus? Schwören die Mitglieder des Teams Rache?","sz":9.5,"box":[53.9,422.2,283.8,481.7],"p":60,"i":3,"sec":"der-kontrollraum"},{"t":"p","x":"• Was wurde aus Maximilian Drake, dem Mechanist? Konnte er jemanden mit seinen selbstgefälligen philosophischen Reden überzeugen? Hat er seine Fehler eingesehen oder akzeptiert, dass es mehr zwischen Himmel und Erde gibt, als die Schulweisheit sich träumen lässt? Ist er nun noch überzeugter von seinen Ansichten? Wie will das Team verhindern, dass er noch mehr Risse ermordet?","sz":9.5,"box":[53.9,490.4,285.1,587.4],"p":60,"i":4,"sec":"der-kontrollraum"},{"t":"p","x":"• Wie geht es weiter mit dem Rummel? Wenn Drake frei ist, wird er seine Vision verwirklichen und den Risse tötenden Themenpark eröffnen, den er konzipiert hat? Was werden die Lemnos-Schausteller:innen tun, wenn ihr Gott verschwunden ist? Werden sie in den Trümmern des Rummelplatzes auf seine Rückkehr warten? Werden sie alles aufbauen, als legitimen Vergnügungspark eröffnen oder das Vermächtnis ihres Meisters fortführen?","sz":9.5,"box":[53.9,596.0,285.3,705.5],"p":60,"i":5,"sec":"der-kontrollraum"},{"t":"p","x":"• Wie will das Team mit der Organisation Heilung für die Gebrochenen umgehen? Wenn ihr <i>Der sanfte Tod</i> gespielt habt, haben die SC jetzt schon zwei Schurk:innen getroffen, die mit der Therapeut:innengruppe in Verbindung stehen.","sz":9.5,"box":[53.9,714.2,279.4,773.7],"p":60,"i":6,"sec":"der-kontrollraum"},{"t":"p","x":"• Jemanden verprügeln, hochheben und herumschleudern oder mit seinem gewaltigen Schmiedehammer zuschlagen (<t>gebrochene Gliedmaßen 4</t>) • Einen Flammenwerfer benutzen (jeder in Reichweite bekommt <t>brennend 2</t>, nach jeder Bewegung erneut, bis der Zustand aufgehoben oder das Feuer gelöscht ist) • Aggressiv predigen, dass Risse keine Legenden, sondern bloß Maschinen sind (alle zuhörenden Risse erhalten <t>Selbstzweifel 1</t>) • Von einem Feuerstrahl angetrieben abheben und wegfliegen (<b>Ihnen etwas verweigern, das sie wollen</b>)","sz":9.0,"box":[317.5,59.9,528.2,213.0],"p":60,"i":7,"sec":"der-kontrollraum"},{"t":"p","x":"• Risse verspotten • Jemandem herablassend erklären, warum seine Kräfte bei ihm nicht funktionieren","sz":9.0,"box":[317.5,221.9,513.8,254.9],"p":60,"i":8,"sec":"der-kontrollraum"},{"t":"p","x":"• Was ist aus Goldie geworden? Hat sie es lebend aus der Todesfalle geschafft, die Drake ihr gestellt hat, oder haben die mythischen und irdischen Triebe ihren Untergang besiegelt? Wenn sie überlebt hat, hat sie Buße getan oder stiehlt sie weite? Vielleicht wird sie ein fester Bestandteil der Serie, verfolgt das Team und begibt sich in gefährliche Situationen.","sz":9.5,"box":[309.0,375.6,536.2,460.1],"p":60,"i":9,"sec":"der-kontrollraum"},{"t":"p","x":"• Hat Detektiv Holliday überlebt? Ist er Goldie gefolgt und in das Rummelplatzdrama geraten? Wird das Team ihn für die Beteiligung am Tod Pauline Woodworths und David Nguyens verantwortlich machen?","sz":9.5,"box":[309.0,468.7,536.9,515.7],"p":60,"i":10,"sec":"der-kontrollraum"},{"t":"p","x":"• Was ist mit Ellie? Wird ihr jemand sagen, dass Pauline tot ist? Dass David Nguyen sie getötet hat? Würde der Anblick der riesigen Leiche Ellie dazu bringen zu erwachen und sich der Subkultur der Risse anzuschließen? Oder erspart das Team ihr die Wahrheit und lässt ihr die Hoffnung, Pauline eines Tages wiederzusehen?","sz":9.5,"box":[309.0,524.4,541.0,608.9],"p":60,"i":11,"sec":"der-kontrollraum"},{"t":"p","x":"• Wenn Theresa Nguyen das Team angeheuert hat, wird sie wissen wollen, was mit Drake passiert ist, es sei denn, sie bekommt seinen Kopf auf dem Silbertablett, wie sie es verlangt. Eine so brutale Tat wird dem Team einen schlechten Ruf einbringen.","sz":9.5,"box":[309.0,617.6,537.9,677.1],"p":60,"i":12,"sec":"der-kontrollraum"},{"t":"p","x":"• Was ist mit Drakes Technologie, die nun im Schlamm herumliegt? Jemand könnte ein magisches Teilnehmen und als Relikt verwenden, wissentlich oder unwissentlich. Ein neuer Riss könnte geboren werden.","sz":9.5,"box":[309.0,685.7,541.0,732.7],"p":60,"i":13,"sec":"der-kontrollraum"}],"size":[595.276,841.89]}},"figures":[{"id":"eisberg","page":44,"kind":"eisberg","title":"Der Eisberg","file":"img/case02/eisberg.webp","box":[0,0,595,470],"after":null},{"id":"unfall-auto","page":43,"kind":"art","title":"Unfall: außer Kontrolle geratenes Auto","file":"img/case02/unfall-auto.webp","box":[40,476,534,795],"after":null},{"id":"diner-detektiv","page":49,"kind":"art","title":"Detektiv vor Rondo's Diner","file":"img/case02/diner-detektiv.webp","box":[0,460,595,795],"after":null},{"id":"rummelplatz","page":53,"kind":"art","title":"Der verlassene Rummelplatz","file":"img/case02/rummelplatz.webp","box":[0,640,595,795],"after":null},{"id":"rummelplatz-plan","page":55,"kind":"plan","title":"Bauplan des Rummelplatzes","file":"img/case02/rummelplatz-plan.webp","box":[37,370,593,752],"after":null},{"id":"yolanda","page":57,"kind":"art","title":"Schausteller von Lemnos","file":"img/case02/yolanda.webp","box":[306,0,595,795],"after":null}],"eisberg":{"page":44,"fig":"eisberg","nodes":[{"label":"Theresa Nguyen","layer":0,"x":34.2,"y":10.8,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Autounfallstelle","layer":0,"x":49.2,"y":10.4,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Officers Das & Quinn","layer":0,"x":64.8,"y":10.8,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Goldie","layer":1,"x":30.6,"y":18.5,"w":11,"h":9.5,"target":"goldie"},{"label":"Privatdetektiv Holliday","layer":1,"x":44.7,"y":18.5,"w":11,"h":9.5,"target":"schicht-1-desaster-in-der-innenstadt"},{"label":"Ecke Pine und 5th","layer":1,"x":58.1,"y":18.1,"w":11,"h":9.5,"target":"ecke-pine-und-5th"},{"label":"Rondo's Diner und Shinobi Sushi","layer":1,"x":71.7,"y":17.7,"w":11,"h":9.5,"target":"rondo-s-diner-und-shinobi-sushi"},{"label":"David Nguyens Wohnung","layer":2,"x":35.3,"y":27.5,"w":11,"h":9.5,"target":"david-nguyens-wohnung"},{"label":"Detektei Holliday","layer":2,"x":49.4,"y":27.5,"w":11,"h":9.5,"target":"detektei-holliday"},{"label":"Wohnung der Woodworths","layer":2,"x":62.2,"y":26.3,"w":11,"h":9.5,"target":"die-wohnung-der-woodworths"},{"label":"Der Spuk","layer":2,"x":75.3,"y":26.7,"w":11,"h":9.5,"target":"der-spuk"},{"label":"Verlassener Rummelplatz","layer":3,"x":53.3,"y":35.0,"w":11,"h":9.5,"target":"verlassener-rummelplatz"},{"label":"Kontrollraum","layer":4,"x":49.2,"y":43.2,"w":11,"h":9.5,"target":"der-kontrollraum"}]}};
